/* Kelas IX — Semester 2 — Kisah Perjuangan Dakwah Nabi & Sahabat — 50 soal */
window.BSRegister({
'id':'k9-kisah-dakwah-nabi','grade':9,'semester':2,'order':20,
'title':'Kisah Perjuangan Dakwah Nabi & Sahabat',
'desc':'Tahapan dakwah Nabi di Makkah dan Madinah, bentuk penentangan kaum Quraisy, hijrah sebagai strategi dakwah, perjuangan para sahabat dalam menyebarkan Islam, serta keteladanan yang dapat diterapkan dalam kehidupan sehari-hari.',
'kd':'Menganalisis tahapan dakwah Rasulullah di Makkah dan Madinah, bentuk penentangan kaum Quraisy, perjuangan para sahabat dalam menyebarkan Islam, serta menampilkan perilaku meneladani perjuangan dakwah Rasulullah dan para sahabat.',
'questions':[{level:'HOTS',indicator:'Menentukan sebab dakwah dimulai secara sembunyi-sembunyi',text:'Dakwah Rasulullah pada tahap pertama dilaksanakan secara sembunyi-sembunyi selama sekitar tiga tahun. Alasan yang paling tepat terhadap cara tersebut adalah ...',options:['agar masyarakat Makkah tidak merasa terkejut sehingga penolakan yang timbul tidak terlalu berarti','agar jumlah pengikut bertambah banyak sebelum dakwah disampaikan secara terbuka','agar Rasulullah dapat berdakwah tanpa diketahui oleh keluarganya sehingga keluarganya tidak terancam','dakwah baru tidak langsung menghadapi penentangan yang keras dari masyarakat'],answer:3,explanation:'Q.S. al-Hijr [15]: 94 berbunyi maka sampaikanlah secara terang-terangan apa yang diperintahkan kepadamu dan berpalinglah dari orang-orang musyrik, yang menunjukkan bahwa perintah menyampaikan secara terang-terangan turun setelah tahap penyampaian yang terbatas. Q.S. asy-Syuara [26]: 214 berbunyi dan berilah peringatan kepada kerabat-kerabatmu yang terdekat, yang merupakan ayat yang memerintahkan memulai dari lingkaran yang terdekat. Sejarah mencatat bahwa pengikut pertama terdiri dari Khadijah, Abu Bakar, Ali, Zaid bin Haritsah, dan pihak yang masuk Islam melalui perantaraan Abu Bakar seperti Utsman, Zubair, Talhah, Saad bin Abi Waqqas, dan Abdurrahman bin Auf. Sejarah juga mencatat pembinaan melalui rumah al-Arqam bin Abi al-Arqam sebagai tempat berkumpul yang terbatas. Hadis juga menyebut bahwa mukmin yang kuat lebih baik dan lebih dicintai Allah daripada mukmin yang lemah. Adapun dakwah sembunyi-sembunyi bukan dimaksudkan untuk menyembunyikan dari keluarga karena keluarga justru merupakan pihak yang pertama kali diajak sebagaimana Q.S. asy-Syuara [26]: 214.'},
{level:'HOTS',indicator:'Menganalisis bentuk penentangan kaum Quraisy terhadap dakwah',text:'Bentuk penentangan kaum Quraisy terhadap dakwah Rasulullah yang paling tepat adalah ...',options:['penentangan yang bersifat ucapan, tekanan sosial, dan penyiksaan fisik terhadap pihak yang lemah','penentangan yang hanya ditujukan kepada Rasulullah sehingga pengikutnya tidak mengalami gangguan dari masyarakat Makkah','penentangan yang hanya bersifat ucapan sehingga tidak terdapat gangguan fisik terhadap pengikut Rasulullah','menuduh, mengolok-olok ayat, dan menyebarkan keraguan di masyarakat'],answer:3,explanation:'Q.S. al-Muddassir [74]: 11-25 menceritakan Walid bin Mughirah yang memikirkan tuduhan yang akan disematkan kepada Al-Quran lalu menyatakan bahwa ini tidak lain hanyalah sihir yang dipelajari dan ini tidak lain hanyalah perkataan manusia. Q.S. Fussilat [41]: 26 berbunyi dan orang-orang yang kafir berkata janganlah kalian mendengarkan Al-Quran ini dan buatlah kegaduhan terhadapnya agar kalian dapat mengalahkan. Q.S. al-Kafirun [109]: 1-6 menggambarkan penolakan terhadap tawaran kompromi dalam beribadah. Q.S. al-Ankabut [29]: 2-3 berbunyi apakah manusia mengira bahwa mereka akan dibiarkan hanya dengan mengatakan kami telah beriman sedangkan mereka tidak diuji. Hadis juga menyebut kisah Bilal yang disiksa dan tetap mengucapkan satu satu yaitu Allah Maha Esa. Sejarah mencatat pemboikotan terhadap Bani Hasyim dan Bani Muttalib selama sekitar tiga tahun yang ditulis dalam lembaran dan digantung di Kakbah. Adapun penentangan kaum Quraisy tidak terbatas pada ucapan karena penyiksaan fisik tercatat menimpa pengikut yang lemah, dan penentangan tidak terbatas pada Rasulullah karena pengikutnya juga mengalami gangguan.'},
{level:'HOTS',indicator:'Menentukan hikmah keteguhan Rasulullah menghadapi penentangan',text:'Hikmah keteguhan Rasulullah dalam menghadapi penentangan kaum Quraisy bagi umat yang datang kemudian adalah ...',options:['menyampaikan kebenaran memerlukan kesabaran panjang dan tidak segera diterima','agar umat mengetahui bahwa penentangan merupakan tanda bahwa dakwah yang disampaikan merupakan dakwah yang benar','agar umat tidak menyampaikan kebenaran kepada masyarakat yang menentang karena penyampaian kepada masyarakat yang demikian hanya menghasilkan permusuhan','agar umat memahami bahwa menyampaikan kebenaran memerlukan kesabaran dan tidak selalu segera diterima'],answer:0,explanation:'Q.S. al-Ankabut [29]: 2-3 berbunyi apakah manusia mengira bahwa mereka akan dibiarkan hanya dengan mengatakan kami telah beriman sedangkan mereka tidak diuji, dan sungguh Kami telah menguji orang-orang sebelum mereka maka Allah benar-benar mengetahui orang-orang yang benar dan benar-benar mengetahui orang-orang yang dusta. Q.S. al-Ahqaf [46]: 35 berbunyi maka bersabarlah engkau sebagaimana kesabaran para rasul yang memiliki keteguhan. Hadis juga menceritakan Rasulullah di Thaif yang dilempari batu hingga berdarah lalu malaikat penjaga gunung menawarkan untuk menimpakan dua gunung kepada penduduknya tetapi Rasulullah menolak dan menyatakan bahwa ia berharap Allah mengeluarkan dari keturunan mereka pihak yang menyembah Allah dan tidak mempersekutukan-Nya. Hadis juga menyebut bahwa perbanyaklah mengingat pemutus kenikmatan yaitu kematian. Q.S. al-Insyirah [94]: 5-6 berbunyi bersama kesulitan terdapat kemudahan. Adapun penentangan bukan tanda pasti bahwa dakwah itu benar karena penentangan juga dapat timbul karena cara penyampaian yang keliru, dan menyampaikan kebenaran kepada masyarakat yang menentang tetap merupakan kewajiban dengan cara yang bijaksana.'},
{level:'HOTS',indicator:'Menganalisis sebab hijrah ke Habsyah',text:'Sebagian sahabat diperintahkan berhijrah ke Habsyah sebelum hijrah ke Madinah. Analisis yang paling tepat terhadap sebab hijrah tersebut adalah ...',options:['agar kaum muslimin memperoleh bantuan pasukan dari Habsyah untuk menghadapi kaum Quraisy di Makkah','agar kaum muslimin meninggalkan Islam secara sementara hingga keadaan di Makkah menjadi aman sehingga dapat kembali menjalankan keyakinannya','memperoleh tempat aman beribadah karena tekanan telah membahayakan keselamatan','agar memperoleh tempat yang aman untuk beribadah dan agar dakwah memperoleh kesempatan berkembang di luar Makkah'],answer:2,explanation:'Sejarah mencatat dua gelombang hijrah ke Habsyah yaitu pada tahun kelima kenabian yang terdiri dari sekitar dua belas laki-laki dan empat perempuan kemudian gelombang berikutnya yang lebih banyak. Hadis juga menyebut bahwa Rasulullah bersabda pergilah kalian ke negeri Habsyah karena di dalamnya terdapat seorang raja yang tidak ada seorang pun dizalimi di bawah kekuasaannya hingga Allah memberi jalan keluar bagi kalian. Sejarah juga mencatat peristiwa Ja far bin Abi Thalib yang membacakan ayat tentang Maryam di hadapan Najasyi sehingga Najasyi mengakui kebenaran kenabian Rasulullah dan menolak menyerahkan kaum muslimin kepada utusan Quraisy. Q.S. an-Nisa [4]: 97-100 menyebut keutamaan berhijrah di jalan Allah dan menyebut bahwa barangsiapa berhijrah di jalan Allah niscaya ia memperoleh di muka bumi ini tempat hijrah yang luas dan rezeki yang banyak. Hadis juga menyebut bahwa amal bergantung pada niatnya. Adapun hijrah ke Habsyah bukan untuk memperoleh bantuan pasukan karena tidak tercatat permintaan bantuan militer kepada Najasyi, dan hijrah bukan berarti meninggalkan Islam melainkan menyelamatkan keimanan.'},
{level:'HOTS',indicator:'Menentukan kandungan peristiwa Baiat Aqabah',text:'Kandungan peristiwa Baiat Aqabah yang paling tepat adalah ...',options:['kesediaan penduduk Yatsrib memberikan harta kepada Rasulullah agar dakwahnya dapat berkembang tanpa gangguan kaum Quraisy','kesediaan penduduk Yatsrib berperang melawan kaum Quraisy di Makkah untuk membebaskan Rasulullah dari tekanan masyarakatnya','kesediaan penduduk Yatsrib beriman kepada Rasulullah dan berjanji melindungi serta menjadi dasar pendirian masyarakat Islam di Madinah','kesediaan beriman dan berjanji meninggalkan perbuatan yang dilarang'],answer:3,explanation:'Sejarah mencatat Baiat Aqabah pertama pada tahun kedua belas kenabian yang diikuti oleh sekitar dua belas orang dari Khazraj dan Aus dengan isi baiat yang berkaitan dengan akidah dan akhlak, lalu Rasulullah mengutus Musab bin Umair untuk membina mereka. Sejarah juga mencatat Baiat Aqabah kedua pada tahun ketiga belas kenabian yang diikuti oleh sekitar tujuh puluh laki-laki dan dua perempuan dengan isi kesediaan melindungi Rasulullah sebagaimana mereka melindungi diri dan keluarga mereka. Q.S. al-Mumtahanah [60]: 12 menggambarkan isi baiat kaum perempuan yaitu tidak mempersekutukan Allah, tidak mencuri, tidak berzina, tidak membunuh anak, tidak membawa kedustaan, dan tidak mendurhakai dalam hal yang baik. Hadis juga menyebut bahwa tidak ada ketaatan kepada makhluk dalam bermaksiat kepada Allah dan ketaatan hanya dalam hal yang baik. Q.S. an-Nisa [4]: 97 menyebut keutamaan berhijrah. Adapun baiat itu bukan perjanjian memberikan harta kepada Rasulullah dan bukan perjanjian berperang ke Makkah karena yang dijanjikan adalah perlindungan di Madinah bukan serangan ke Makkah.'},
{level:'HOTS',indicator:'Menganalisis hikmah dipilihnya Madinah sebagai tempat hijrah',text:'Hikmah dipilihnya Madinah sebagai tempat hijrah yang paling tepat adalah ...',options:['karena penduduk Madinah meminta Rasulullah berkuasa atas mereka sehingga Rasulullah memperoleh kedudukan politik yang tidak diperolehnya di Makkah','karena Madinah merupakan kota yang paling kaya di jazirah Arab sehingga kaum muslimin dapat memperoleh harta untuk mengembangkan dakwah','masyarakat Madinah telah beriman sehingga terdapat dasar pendirian masyarakat','karena masyarakatnya telah beriman melalui dakwah yang dipersiapkan sehingga terdapat dasar bagi pendirian masyarakat Islam'],answer:2,explanation:'Sejarah mencatat bahwa Rasulullah menawarkan dirinya kepada berbagai kabilah pada musim haji sebelum akhirnya memperoleh sambutan dari penduduk Yatsrib, sehingga Madinah bukan pilihan yang pertama melainkan pilihan yang diterima setelah penolakan di tempat lain. Sejarah juga mencatat pengutusan Musab bin Umair ke Yatsrib yang berhasil mengajak banyak penduduk masuk Islam sehingga setiap rumah kaum Ansar terisi oleh orang yang beriman. Sejarah juga mencatat Baiat Aqabah kedua yang berisi kesediaan melindungi Rasulullah. Hadis juga menyebut bahwa tidak ada yang membuat Rasulullah berhijrah kecuali karena ia diusir dari Makkah, sehingga hijrah bukan untuk memperoleh kedudukan politik. Q.S. al-Anfal [8]: 26 berbunyi dan ingatlah ketika kalian masih sedikit dan tertindas di muka bumi, kalian takut orang-orang akan menculik kalian maka Allah memberi kalian tempat menetap yaitu Madinah. Adapun kekayaan Madinah bukan alasan utama karena keadaan kaum Muhajirin ketika tiba justru dalam keadaan tidak memiliki harta, dan kedudukan geografis Madinah merupakan faktor pendukung bukan faktor utama.'},
{level:'HOTS',indicator:'Menentukan langkah pertama Rasulullah setelah tiba di Madinah',text:'Langkah pertama Rasulullah setelah tiba di Madinah yang paling tepat adalah ...',options:['membangun pasar agar perekonomian Madinah berkembang sehingga kaum Muhajirin memperoleh penghasilan yang mencukupi','membangun benteng pertahanan agar Madinah terlindungi dari serangan kaum Quraisy yang mungkin menyusul','membangun masjid sebagai pusat ibadah dan mempersaudarakan Muhajirin Ansar','membangun masjid, mempersaudarakan Muhajirin dan Ansar, serta membuat perjanjian dengan seluruh kelompok masyarakat'],answer:2,explanation:'Sejarah mencatat bahwa Rasulullah membangun masjid di tempat untanya berhenti yaitu di tanah milik dua anak yatim yang diasuh oleh Asad bin Zurarah dari Bani Najjar. Sejarah juga mencatat persaudaraan antara kaum Muhajirin dan kaum Ansar yang di antaranya adalah persaudaraan antara Abdurrahman bin Auf dan Saad bin Rabi. Sejarah juga mencatat Piagam Madinah yang mengatur hubungan antara kaum muslimin, kelompok Yahudi, dan kelompok lain di Madinah dengan ketentuan tentang hak, kewajiban, dan penyelesaian perselisihan. Q.S. al-Hasyr [59]: 9 menggambarkan kaum Ansar yang mengutamakan orang lain atas diri mereka sendiri walaupun diri mereka memerlukan. Hadis juga menyebut bahwa sebaik-baik kalian adalah yang paling baik terhadap keluarganya dan terhadap sahabatnya. Hadis juga menyebut bahwa tangan yang di atas lebih baik daripada tangan yang di bawah. Adapun membangun pasar dan benteng bukan langkah pertama yang tercatat karena pengaturan ekonomi dilakukan melalui dorongan bekerja dan pengaturan keamanan dilakukan melalui perjanjian dengan seluruh kelompok masyarakat.'},
{level:'HOTS',indicator:'Menganalisis keteladanan persaudaraan Muhajirin dan Ansar',text:'Keteladanan yang paling tepat dari persaudaraan antara kaum Muhajirin dan kaum Ansar bagi kehidupan bermasyarakat adalah ...',options:['kesediaan berbagi dengan pihak yang memerlukan dan kesediaan menerima bantuan tanpa bergantung dalam waktu yang lama','kesediaan memberi seluruh harta kepada pihak yang memerlukan sehingga pemberi tidak memerlukan apa pun lagi','kesediaan menerima seluruh tawaran bantuan karena menolak bantuan merupakan bentuk tidak menghargai kebaikan pihak yang memberi','kesediaan berbagi walaupun diri sendiri memerlukannya dan menerima bantuan'],answer:3,explanation:'Q.S. al-Hasyr [59]: 9 berbunyi dan orang-orang yang telah menempati kota Madinah dan telah beriman sebelum kedatangan mereka mencintai orang yang berhijrah kepada mereka dan tidak menaruh keinginan dalam hati mereka terhadap apa yang diberikan kepada mereka dan mengutamakan orang lain atas diri mereka sendiri walaupun diri mereka memerlukan, dan siapa yang dipelihara dari kekikiran maka mereka itulah orang yang beruntung. Q.S. al-Anfal [8]: 72-73 menyebut ikatan antara kaum mukmin yang berhijrah dan yang memberi tempat serta menolong. Sejarah mencatat bahwa Saad bin Rabi menawarkan separuh hartanya dan salah seorang istrinya kepada Abdurrahman bin Auf tetapi Abdurrahman menolak dengan sopan dan hanya meminta ditunjukkan arah pasar. Hadis juga menyebut bahwa tangan yang di atas lebih baik daripada tangan yang di bawah. Hadis juga menyebut bahwa tidak beriman seseorang hingga mencintai saudaranya sebagaimana mencintai dirinya sendiri. Adapun memberi seluruh harta hingga tidak memerlukan apa pun bukan cara yang diajarkan karena pemberi tetap memiliki kewajiban terhadap dirinya dan keluarganya, dan menolak tawaran bantuan dengan sopan sambil memilih memulai usaha sendiri bukan bentuk tidak menghargai kebaikan.'},
{level:'HOTS',indicator:'Menentukan perjuangan para sahabat dalam menyebarkan Islam setelah Rasulullah wafat',text:'Perjuangan para sahabat dalam menyebarkan Islam setelah Rasulullah wafat yang paling tepat adalah ...',options:['berjuang mempertahankan wilayah Madinah saja karena memperluas wilayah menghasilkan tanggung jawab yang terlalu berat','menjaga kesatuan umat, menyelesaikan persoalan yang timbul, dan memperluas penyampaian Islam ke luar jazirah Arab','berjuang memperoleh harta dari wilayah yang ditaklukkan agar kaum muslimin memperoleh kekayaan yang mencukupi','menjaga kesatuan umat dan menyebarkan Islam ke wilayah yang luas'],answer:3,explanation:'Sejarah mencatat bahwa Abu Bakar menangani persoalan kelompok yang menolak menunaikan zakat dengan menyatakan bahwa demi Allah ia akan memerangi pihak yang memisahkan antara salat dan zakat. Sejarah juga mencatat pengumpulan Al-Quran pada masa Abu Bakar setelah Perang Yamamah yang mengakibatkan banyak penghafal Al-Quran gugur, atas usulan Umar dan dilaksanakan oleh Zaid bin Tsabit. Sejarah juga mencatat penyatuan mushaf pada masa Utsman sehingga perbedaan bacaan yang memicu perselisihan dapat dicegah. Q.S. at-Taubah [9]: 122 berbunyi tidak sepatutnya orang-orang mukmin itu pergi semuanya ke medan perang, mengapa tidak pergi dari tiap-tiap golongan di antara mereka beberapa orang untuk memperdalam pengetahuan agama. Hadis juga menyebut bahwa sampaikanlah dariku walaupun satu ayat. Q.S. al-Anbiya [21]: 107 menyebut bahwa Rasulullah diutus sebagai rahmat bagi seluruh alam, sehingga penyampaian Islam tidak terbatas pada jazirah Arab. Adapun perjuangan memperoleh harta bukan tujuan karena sejarah mencatat bahwa para pemimpin pasukan memerintahkan mengembalikan pajak perlindungan ketika tidak mampu melindungi, dan mempertahankan Madinah saja bukan pilihan yang diambil karena para sahabat memahami kewajiban menyampaikan Islam ke wilayah yang lain.'},
{level:'HOTS',indicator:'Menganalisis keteladanan Bilal bin Rabah dalam mempertahankan keimanan',text:'Keteladanan yang paling tepat dari Bilal bin Rabah yang disiksa tetapi tetap mempertahankan keimanannya adalah ...',options:['keteguhan yang lahir dari harapan memperoleh kedudukan di sisi Rasulullah sehingga kesabarannya merupakan kesabaran yang mengharapkan imbalan','keyakinan bahwa penyiksaan akan segera berakhir sehingga kesabarannya merupakan kesabaran yang berjangka pendek','keyakinan yang tidak dapat ditukar dengan keselamatan walaupun keselamatan itu sangat berharga','keyakinan tidak dapat ditukar dengan keselamatan atau kenyamanan dunia'],answer:3,explanation:'Sejarah mencatat bahwa Bilal dijemur di padang pasir di bawah panas matahari dan dihimpit dengan batu besar sambil dipaksa meninggalkan keimanannya tetapi ia tetap mengucapkan satu satu yaitu Allah Maha Esa, hingga Abu Bakar membebaskannya dengan membeli dari tuannya. Q.S. an-Nahl [16]: 106 berbunyi barangsiapa kafir kepada Allah setelah beriman maka ia memperoleh kemurkaan Allah kecuali orang yang dipaksa sedangkan hatinya tetap tenang dengan keimanan. Q.S. al-Ankabut [29]: 2-3 menyebut bahwa manusia akan diuji untuk membuktikan kebenaran pengakuan imannya. Q.S. al-Hujurat [49]: 13 menyebut bahwa yang paling mulia di sisi Allah adalah yang paling bertakwa. Hadis juga menyebut bahwa Allah tidak melihat kepada rupa dan harta kalian melainkan kepada hati dan amal kalian. Adapun keteguhan Bilal bukan kesabaran yang berjangka pendek karena ia bertahan dalam penyiksaan yang berlangsung hingga dibebaskan, dan keteguhannya bukan karena harapan memperoleh kedudukan karena ketika disiksa ia belum mengetahui bahwa ia akan memperoleh kedudukan sebagai muazin Rasulullah.'},
{level:'HOTS',indicator:'Menentukan keteladanan keluarga Yasir dalam mempertahankan keimanan',text:'Keteladanan yang paling tepat dari keluarga Yasir dalam mempertahankan keimanan adalah ...',options:['keteguhan yang hanya berlaku bagi laki-laki sehingga perempuan tidak memperoleh kedudukan yang sama dalam mempertahankan keimanan','kesabaran sekeluarga menghadapi penyiksaan sehingga tetap beriman semuanya','kesabaran sekeluarga dalam menghadapi penyiksaan sehingga seluruh anggota keluarga tetap beriman hingga ada yang gugur sebagai syahidah pertama','kesabaran yang lahir dari keyakinan bahwa mereka akan memperoleh balasan dunia sehingga pengorbanannya merupakan investasi yang menguntungkan'],answer:1,explanation:'Sejarah mencatat bahwa keluarga Yasir yaitu Yasir, Sumayyah, dan Ammar disiksa karena keimanannya dan Sumayyah gugur karena ditusuk dengan tombak sehingga menjadi perempuan pertama yang gugur sebagai syahidah. Sejarah juga mencatat bahwa Ammar mengucapkan kata yang menunjukkan kekufuran karena tidak sanggup menahan penyiksaan lalu melaporkan hal itu kepada Rasulullah dan Rasulullah bertanya bagaimana keadaan hatimu, Ammar menjawab tetap tenang dengan keimanan, lalu Rasulullah bersabda apabila mereka mengulang maka ulangilah ucapan itu, dan turun Q.S. an-Nahl [16]: 106 yang mengecualikan orang yang dipaksa sedangkan hatinya tetap tenang dengan keimanan. Sejarah juga mencatat ucapan Rasulullah ketika melewati keluarga Yasir yaitu bersabarlah wahai keluarga Yasir karena sesungguhnya janji kalian adalah surga. Q.S. al-Ankabut [29]: 2-3 menyebut bahwa manusia akan diuji. Adapun keteguhan keluarga Yasir bukan karena harapan memperoleh balasan dunia karena mereka justru kehilangan nyawa dan kenyamanan, dan keteguhan dalam mempertahankan keimanan berlaku bagi laki-laki dan perempuan sehingga Sumayyah memperoleh kedudukan sebagai syahidah pertama.'},
{level:'HOTS',indicator:'Menganalisis strategi dakwah Rasulullah dalam menyampaikan Islam',text:'Strategi dakwah Rasulullah dalam menyampaikan Islam yang paling tepat adalah ...',options:['memulai dari kerabat terdekat lalu menyampaikan kepada masyarakat luas','memulai dari kerabat terdekat, memilih tempat yang terbuka untuk menyampaikan kepada masyarakat luas, dan mendatangi kabilah pada musim berkumpulnya masyarakat','menyampaikan dakwah secara terbuka sejak awal agar tidak ada pihak yang merasa disembunyikan informasi tentang agama yang baru','memulai dari pihak yang paling berpengaruh agar masyarakat mengikuti tanpa mempertimbangkan pemahaman mereka'],answer:0,explanation:'Q.S. asy-Syuara [26]: 214 berbunyi dan berilah peringatan kepada kerabat-kerabatmu yang terdekat. Q.S. al-Hijr [15]: 94 memerintahkan menyampaikan secara terang-terangan apa yang diperintahkan. Sejarah mencatat bahwa Rasulullah menyampaikan peringatan di bukit Shafa dengan mengumpulkan kabilah-kabilah Quraisy. Sejarah juga mencatat bahwa Rasulullah menawarkan dirinya kepada kabilah-kabilah pada musim haji dan di pasar Ukaz hingga memperoleh sambutan dari penduduk Yatsrib. Sejarah juga mencatat bahwa banyak pihak masuk Islam melalui perantaraan Abu Bakar seperti Utsman, Zubair, Talhah, Saad bin Abi Waqqas, dan Abdurrahman bin Auf. Sejarah juga mencatat pembinaan di rumah al-Arqam bin Abi al-Arqam. Q.S. an-Nahl [16]: 125 memerintahkan menyeru dengan hikmah, nasihat yang baik, dan berdebat dengan cara yang terbaik, yang menunjukkan perlunya menyesuaikan cara dengan keadaan pihak yang diajak. Adapun memulai dari pihak yang paling berpengaruh tanpa memperhatikan pemahaman bukan strategi yang tepat karena pemahaman merupakan dasar keteguhan, dan menyampaikan secara terbuka sejak awal bukan cara yang dipilih karena perintah menyampaikan secara terang-terangan turun setelah tahap pembinaan yang terbatas.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam bersikap terhadap pihak yang menentang',text:'Keteladanan Rasulullah dalam bersikap terhadap pihak yang menentangnya yang paling tepat adalah ...',options:['membalas penentangan dengan cara yang setimpal agar pihak yang menentang menyadari akibat dari perbuatannya','tidak membalas dengan cara yang dilarang, mendoakan petunjuk bagi mereka, dan memaafkan ketika telah mampu membalas','memutuskan seluruh hubungan dengan pihak yang menentang agar tidak lagi memperoleh gangguan dari mereka','tidak membalas dengan cara dilarang dan mendoakan petunjuk bagi penentang'],answer:3,explanation:'Q.S. Ali Imran [3]: 159 berbunyi maka berkat rahmat Allah engkau berlaku lemah lembut terhadap mereka, dan seandainya engkau bersikap keras dan berhati kasar niscaya mereka menjauh dari sekitarmu. Q.S. al-Anbiya [21]: 107 berbunyi dan Kami tidak mengutus engkau melainkan sebagai rahmat bagi seluruh alam. Hadis juga menyebut kisah Rasulullah di Thaif yang menolak tawaran malaikat penjaga gunung dan menyatakan bahwa ia berharap Allah mengeluarkan dari keturunan mereka pihak yang menyembah Allah dan tidak mempersekutukan-Nya. Hadis juga menyebut kisah Rasulullah yang berdoa untuk kaumnya ketika mereka melemparinya sehingga berlumuran darahnya sambil menyatakan ya Allah berilah petunjuk kepada kaumku karena mereka tidak mengetahui. Sejarah mencatat pernyataan Rasulullah pada penaklukan Makkah yaitu pergilah karena kalian bebas. Q.S. al-Mumtahanah [60]: 8 menyebut bahwa Allah tidak melarang berbuat baik dan berlaku adil terhadap orang yang tidak memerangi karena agama. Adapun membalas dengan cara yang setimpal dibolehkan dalam batas tertentu tetapi memaafkan lebih utama sebagaimana Q.S. asy-Syura [42]: 40, dan memutuskan seluruh hubungan bukan cara yang diambil karena Rasulullah tetap membuka kesempatan bagi pihak yang menentang untuk beriman.'},
{level:'HOTS',indicator:'Menganalisis hikmah peristiwa perjanjian Hudaibiyah yang tampak merugikan',text:'Perjanjian Hudaibiyah tampak merugikan kaum muslimin tetapi disebut dalam Al-Quran sebagai kemenangan yang nyata. Analisis yang paling tepat terhadap hikmah peristiwa tersebut adalah ...',options:['hikmahnya agar umat memahami bahwa ketentuan yang tampak merugikan dapat menghasilkan keuntungan yang lebih besar','hikmahnya agar umat menerima seluruh perjanjian yang ditawarkan oleh pihak lawan karena perjanjian selalu menghasilkan kedamaian','ketentuan yang tampak merugikan dapat menghasilkan keuntungan lebih besar','hikmahnya karena perjanjian Hudaibiyah merupakan perjanjian yang menguntungkan kaum Quraisy sehingga kaum muslimin perlu menolaknya pada kesempatan berikutnya'],answer:2,explanation:'Q.S. al-Fath [48]: 1 berbunyi sesungguhnya Kami telah memberikan kepadamu kemenangan yang nyata, yang turun berkaitan dengan peristiwa Hudaibiyah. Q.S. al-Fath [48]: 18 menyebut bahwa Allah telah mengetahui apa yang ada dalam hati orang-orang yang berjanji di bawah pohon lalu menurunkan ketenangan atas mereka dan memberi balasan dengan kemenangan yang dekat. Q.S. al-Baqarah [2]: 216 berbunyi boleh jadi kalian membenci sesuatu padahal sesuatu itu baik bagi kalian dan boleh jadi kalian menyukai sesuatu padahal sesuatu itu buruk bagi kalian, dan Allah mengetahui sedangkan kalian tidak mengetahui. Sejarah mencatat bahwa Umar menyampaikan keberatannya kepada Rasulullah tentang isi perjanjian itu lalu Rasulullah menyatakan bahwa ia adalah Rasulullah dan tidak akan menyia-nyiakan perintah-Nya, dan setelah turun Q.S. al-Fath Umar menyadari bahwa keputusan itu merupakan kemenangan. Sejarah juga mencatat bahwa jumlah yang masuk Islam setelah perjanjian meningkat secara signifikan karena masa damai memungkinkan penyampaian dakwah. Adapun menerima seluruh perjanjian tanpa pertimbangan bukan pelajaran dari peristiwa itu karena yang benar adalah mempertimbangkan isi perjanjian, dan perjanjian Hudaibiyah bukan perjanjian yang menguntungkan kaum Quraisy secara mutlak karena hasilnya merupakan kemenangan bagi kaum muslimin.'},
{level:'HOTS',indicator:'Menentukan keteladanan Musab bin Umair dalam berdakwah',text:'Keteladanan Musab bin Umair dalam berdakwah di Madinah yang paling tepat adalah ...',options:['meninggalkan kemewahan demi iman dan berdakwah dengan cara bijaksana','meninggalkan kemewahan keluarganya demi keimanan dan berdakwah dengan cara yang bijaksana sehingga banyak penduduk Madinah masuk Islam','berdakwah tanpa meninggalkan kemewahan keluarganya agar tetap memiliki harta untuk membiayai kegiatan dakwahnya','berdakwah dengan cara yang tegas agar penduduk Madinah segera menerima Islam karena ketegasan menghasilkan penerimaan yang cepat'],answer:0,explanation:'Sejarah mencatat bahwa Musab bin Umair merupakan pemuda yang paling baik penampilannya di Makkah dan paling dimanjakan oleh ibunya, tetapi ketika masuk Islam ibunya memutus pemberian sehingga ia hidup dalam keadaan sederhana. Sejarah juga mencatat bahwa Rasulullah mengutusnya ke Yatsrib setelah Baiat Aqabah pertama untuk mengajarkan Al-Quran dan membina masyarakat, dan ia berhasil mengajak banyak penduduk masuk Islam melalui cara yang bijaksana. Sejarah juga mencatat bahwa ketika Saad bin Muadz dan Usaid bin Hudhair datang dengan marah karena khawatir pengaruhnya terhadap masyarakatnya, Musab menjelaskan dengan tenang dan membacakan Al-Quran sehingga keduanya masuk Islam. Hadis juga menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya dan tidaklah kekasaran ada pada sesuatu melainkan ia merusaknya. Q.S. an-Nahl [16]: 125 memerintahkan menyeru dengan hikmah, nasihat yang baik, dan berdebat dengan cara yang terbaik. Sejarah juga mencatat bahwa Musab gugur dalam Perang Uhud sambil memegang bendera dan ketika itu hanya ditemukan kain yang tidak cukup untuk menutup seluruh tubuhnya. Adapun ketegasan bukan cara yang menghasilkan penerimaan dalam peristiwa itu karena yang tercatat adalah kelembutan, dan meninggalkan kemewahan merupakan akibat dari mempertahankan keimanan bukan pilihan yang dapat dihindari.'},
{level:'HOTS',indicator:'Menganalisis hikmah disyariatkannya izin berperang setelah hijrah',text:'Izin berperang turun setelah hijrah ke Madinah bukan pada masa di Makkah. Analisis yang paling tepat terhadap hikmah ketentuan tersebut adalah ...',options:['berperang disyariatkan setelah umat memiliki kekuatan dan wilayah pelindung','hikmahnya karena berperang tidak dibolehkan sama sekali dalam Islam sehingga izin yang turun merupakan pengecualian yang berlaku satu kali','hikmahnya agar kaum muslimin memperoleh kesempatan mengumpulkan harta untuk membiayai peperangan yang akan datang','hikmahnya agar umat memahami bahwa berperang disyariatkan setelah kaum muslimin memiliki kekuatan dan wilayah yang melindungi'],answer:0,explanation:'Q.S. al-Hajj [22]: 39-40 berbunyi telah diizinkan berperang bagi orang-orang yang diperangi karena sesungguhnya mereka telah dizalimi, dan sesungguhnya Allah benar-benar Mahakuasa menolong mereka, yaitu orang-orang yang diusir dari kampung halaman mereka tanpa alasan yang benar kecuali karena mereka berkata Tuhan kami adalah Allah. Q.S. al-Baqarah [2]: 190 berbunyi dan berperanglah di jalan Allah terhadap orang-orang yang memerangi kalian dan janganlah melampaui batas. Q.S. al-Baqarah [2]: 256 berbunyi tidak ada paksaan dalam agama. Q.S. al-Hajj [22]: 40 juga menyebut bahwa seandainya Allah tidak menolak keganasan sebagian manusia dengan sebagian yang lain tentulah telah dirobohkan tempat-tempat ibadah. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya. Adapun mengumpulkan harta untuk membiayai peperangan bukan hikmah utama karena yang menjadi dasar adalah kezaliman yang menimpa kaum muslimin, dan berperang dibolehkan dalam keadaan tertentu dengan ketentuan yang ketat sehingga bukan pengecualian yang berlaku satu kali.'},
{level:'HOTS',indicator:'Menentukan keteladanan Abu Bakar dalam peristiwa hijrah bersama Rasulullah',text:'Keteladanan Abu Bakar dalam peristiwa hijrah bersama Rasulullah yang paling tepat adalah ...',options:['kesediaan menyiapkan perbekalan dari harta kaum muslimin sehingga perjalanannya tidak membebani hartanya sendiri','kesediaan mendampingi karena mengetahui bahwa perjalanan itu akan menghasilkan kedudukan bagi dirinya di Madinah','mendampingi dalam perjalanan berbahaya dan menyiapkan perbekalan sendiri','kesediaan mendampingi dalam keadaan berbahaya, menyiapkan perbekalan dengan hartanya sendiri, dan menenangkan Rasulullah ketika dikejar'],answer:2,explanation:'Q.S. at-Taubah [9]: 40 berbunyi jika kalian tidak menolongnya maka sesungguhnya Allah telah menolongnya ketika orang-orang kafir mengusirnya sedangkan ia salah seorang dari dua orang ketika keduanya berada di dalam gua, yaitu ketika ia berkata kepada sahabatnya janganlah engkau bersedih sesungguhnya Allah bersama kita, maka Allah menurunkan ketenangan kepadanya dan menolongnya dengan bala tentara yang tidak kalian lihat. Sejarah juga mencatat bahwa Abu Bakar menyiapkan dua ekor unta dan perbekalan dari hartanya sendiri serta menyewa Abdullah bin Uraiqith sebagai penunjuk jalan. Sejarah juga mencatat peristiwa Asma binti Abu Bakar yang mengantar makanan dengan mengikatnya pada ikat pinggangnya sehingga mendapat sebutan yang berkemban dua. Hadis juga menyebut bahwa Rasulullah menyatakan apabila aku mengambil kekasih selain Tuhanku niscaya aku mengambil Abu Bakar sebagai kekasih. Hadis juga menyebut bahwa amal bergantung pada niatnya. Adapun Abu Bakar tidak mengharapkan kedudukan karena ia telah memiliki kedudukan yang tinggi sebelum hijrah dan justru meninggalkan hartanya, dan perbekalan disiapkan dari hartanya sendiri bukan dari harta kaum muslimin.'},
{level:'HOTS',indicator:'Menganalisis hikmah dijadikannya dakwah sebagai kewajiban umat',text:'Dakwah merupakan kewajiban umat Islam bukan hanya kewajiban Rasulullah. Analisis yang paling tepat terhadap hikmah ketentuan tersebut adalah ...',options:['ajaran tetap tersebar setelah beliau wafat karena menjadi tanggung jawab','hikmahnya agar ajaran Islam tetap tersebar setelah Rasulullah wafat dan agar umat memperoleh kedudukan sebagai umat terbaik','hikmahnya karena dakwah merupakan cara memperoleh penghasilan sehingga pihak yang berdakwah berhak memperoleh imbalan dari masyarakat','hikmahnya agar umat memperoleh kekuasaan atas masyarakat yang belum beriman sehingga dapat mengatur kehidupan mereka'],answer:0,explanation:'Q.S. Ali Imran [3]: 110 berbunyi kalian adalah umat terbaik yang dilahirkan untuk manusia, menyuruh kepada yang makruf dan mencegah dari yang mungkar serta beriman kepada Allah. Q.S. Ali Imran [3]: 104 berbunyi dan hendaklah ada di antara kalian segolongan umat yang menyeru kepada kebaikan dan menyuruh kepada yang makruf serta mencegah dari yang mungkar, dan mereka itulah orang-orang yang beruntung. Hadis juga menyebut bahwa barangsiapa di antara kalian melihat kemungkaran hendaklah mengubahnya dengan tangan, dengan lisan, atau dengan hati. Hadis juga menyebut bahwa sampaikanlah dariku walaupun satu ayat. Q.S. at-Taubah [9]: 122 menyebut bahwa tidak sepatutnya orang-orang mukmin pergi semuanya ke medan perang melainkan hendaklah dari tiap-tiap golongan ada yang memperdalam pengetahuan agama dan memberi peringatan kepada kaumnya. Hadis juga menyebut bahwa barangsiapa menunjukkan kepada kebaikan maka ia memperoleh pahala seperti pahala orang yang mengerjakannya. Adapun dakwah bukan sarana memperoleh kekuasaan karena Q.S. al-Baqarah [2]: 256 menyebut tidak ada paksaan dalam agama, dan dakwah bukan cara memperoleh penghasilan karena para rasul menyatakan bahwa mereka tidak meminta upah atas penyampaian itu.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam menjaga kesepakatan dengan pihak yang berbeda keyakinan',text:'Keteladanan Rasulullah dalam menjaga kesepakatan dengan pihak yang berbeda keyakinan di Madinah yang paling tepat adalah ...',options:['menepati kesepakatan hanya ketika menguntungkan kaum muslimin dan meninggalkannya ketika keadaannya berubah','menepati kesepakatan selama pihak lain juga menepatinya tanpa mengkhianati','menghukum seluruh kelompok ketika sebagian anggotanya melanggar kesepakatan karena tanggung jawab kelompok merupakan tanggung jawab bersama','menepati kesepakatan selama pihak lain menepatinya dan tidak mengkhianati walaupun pihak lain lebih lemah'],answer:1,explanation:'Q.S. al-Anfal [8]: 58 berbunyi dan jika engkau khawatir akan adanya pengkhianatan dari suatu kaum maka kembalikanlah perjanjian itu kepada mereka dengan cara yang jujur, sesungguhnya Allah tidak menyukai orang-orang yang berkhianat, sehingga kesepakatan dikembalikan secara terbuka bukan dilanggar secara diam-diam. Q.S. an-Nahl [16]: 91 berbunyi dan penuhilah janji apabila kalian berjanji dan janganlah kalian membatalkan sumpah setelah mengukuhkannya. Q.S. al-Mumtahanah [60]: 8 berbunyi Allah tidak melarang kalian berbuat baik dan berlaku adil terhadap orang-orang yang tidak memerangi kalian karena agama dan tidak mengusir kalian dari kampung halaman kalian, sesungguhnya Allah menyukai orang-orang yang berlaku adil. Q.S. al-Maidah [5]: 8 berbunyi dan janganlah kebencian kalian terhadap suatu kaum mendorong kalian untuk berlaku tidak adil, berlaku adillah karena adil itu lebih dekat kepada takwa. Q.S. al-Anam [6]: 164 berbunyi dan seseorang yang berdosa tidak akan memikul dosa orang lain, sehingga menghukum seluruh kelompok karena pelanggaran sebagian anggotanya bukan keadilan. Adapun menepati kesepakatan tidak bergantung pada keuntungan karena kesepakatan merupakan amanah yang berlaku selama pihak lain juga menepatinya.'},
{level:'HOTS',indicator:'Menganalisis hikmah kesulitan yang dihadapi kaum muslimin pada tahap awal dakwah',text:'Kaum muslimin menghadapi kesulitan yang berat pada tahap awal dakwah. Analisis yang paling tepat terhadap hikmah kesulitan tersebut adalah ...',options:['hikmahnya agar kaum muslimin memperoleh simpati dari masyarakat Makkah sehingga jumlah pengikutnya bertambah','hikmahnya karena kesulitan merupakan hukuman atas dosa yang telah dilakukan oleh kaum muslimin pada masa sebelum Islam','keimanan teruji sehingga yang teguh karena keyakinan dapat diketahui','hikmahnya agar keimanan yang dimiliki teruji sehingga yang teguh diketahui dan yang lemah diketahui'],answer:2,explanation:'Q.S. al-Ankabut [29]: 2-3 berbunyi apakah manusia mengira bahwa mereka akan dibiarkan hanya dengan mengatakan kami telah beriman sedangkan mereka tidak diuji, dan sungguh Kami telah menguji orang-orang sebelum mereka maka Allah benar-benar mengetahui orang-orang yang benar dan benar-benar mengetahui orang-orang yang dusta. Q.S. al-Baqarah [2]: 214 berbunyi apakah kalian mengira bahwa kalian akan masuk surga padahal belum datang kepada kalian cobaan sebagaimana halnya orang-orang terdahulu sebelum kalian, mereka ditimpa oleh malapetaka dan kesengsaraan serta diguncangkan hingga berkatalah Rasul dan orang-orang yang beriman bersamanya bilakah datangnya pertolongan Allah. Hadis juga menyebut bahwa manusia yang paling berat ujiannya adalah para nabi kemudian yang paling serupa dengan mereka kemudian yang paling serupa dengan mereka. Q.S. al-Hadid [57]: 10 menyebut perbedaan derajat antara orang yang berinfak sebelum penaklukan Makkah dan sesudahnya. Hadis juga menyebut bahwa tidaklah seorang muslim tertimpa kelelahan, penyakit, kesedihan, kesusahan, gangguan, dan gundah gulana melainkan Allah menghapus sebagian kesalahannya. Adapun memperoleh simpati masyarakat bukan hikmah kesulitan karena masyarakat Makkah justru menambah penentangan, dan kesulitan bukan hukuman atas dosa karena para sahabat yang disiksa merupakan pihak yang paling teguh keimanannya.'},
{level:'HOTS',indicator:'Menentukan keteladanan Umar bin Khattab sebelum dan sesudah masuk Islam',text:'Keteladanan yang paling tepat dari peristiwa masuk Islamnya Umar bin Khattab adalah ...',options:['perubahan itu menunjukkan bahwa pihak yang menentang perlu didekati dengan cara memberikan harta agar bersedia masuk Islam','petunjuk merupakan karunia Allah sehingga tidak ada pihak yang putus asa','perubahan itu menunjukkan bahwa Umar masuk Islam karena takut kepada kaum muslimin yang jumlahnya telah bertambah banyak','perubahan dari pihak yang menentang menjadi pihak yang membela menunjukkan bahwa petunjuk merupakan karunia Allah dan bahwa pihak yang menentang tidak boleh diputus harapan atasnya'],answer:1,explanation:'Sejarah mencatat bahwa Umar berangkat dengan maksud mencelakakan Rasulullah lalu mendengar bacaan Al-Quran dan hatinya terpengaruh sehingga ia masuk Islam, dan riwayat menyebut bahwa Rasulullah berdoa ya Allah muliakanlah Islam dengan salah seorang dari dua orang yang lebih Engkau cintai yaitu Abu Jahal atau Umar bin Khattab, dan yang lebih dicintai oleh Allah adalah Umar. Q.S. al-Qasas [28]: 56 berbunyi sesungguhnya engkau tidak dapat memberi petunjuk kepada orang yang engkau cintai tetapi Allah memberi petunjuk kepada siapa yang dikehendaki-Nya. Q.S. al-Anam [6]: 125 berbunyi barangsiapa yang dikehendaki Allah akan memperoleh petunjuk niscaya Dia melapangkan dadanya untuk Islam. Sejarah mencatat bahwa setelah masuk Islam Umar menyatakan keislamannya secara terbuka dan kaum muslimin dapat melaksanakan salat di dekat Kakbah secara terang-terangan. Hadis juga menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya. Adapun Umar tidak masuk Islam karena takut karena ketika itu jumlah kaum muslimin masih sedikit, dan pendekatan dengan memberikan harta bukan sebab masuk Islamnya Umar karena yang mempengaruhinya adalah bacaan Al-Quran.'},
{level:'HOTS',indicator:'Menganalisis hikmah penaklukan Makkah dilaksanakan tanpa pertumpahan darah',text:'Penaklukan Makkah dilaksanakan tanpa pertumpahan darah dan disertai pengampunan umum. Analisis yang paling tepat terhadap hikmah peristiwa tersebut adalah ...',options:['hikmahnya agar umat memahami bahwa tujuan dakwah merupakan menyampaikan kebenaran bukan membalas dendam','tujuan perjuangan menyampaikan kebenaran bukan membalas dendam','hikmahnya agar kaum Quraisy tidak melawan sehingga penaklukan berlangsung cepat dan tidak memerlukan biaya yang besar','hikmahnya karena pertumpahan darah dilarang dalam seluruh keadaan sehingga kaum muslimin tidak pernah berperang walaupun diserang'],answer:1,explanation:'Sejarah mencatat bahwa Rasulullah memasuki Makkah pada tahun kedelapan hijriah dengan sepuluh ribu pasukan dan menyatakan barangsiapa masuk ke rumah Abu Sufyan maka ia aman, barangsiapa menutup pintunya maka ia aman, dan barangsiapa masuk ke Masjidil Haram maka ia aman, serta menyatakan kepada kaum Quraisy pergilah karena kalian bebas. Q.S. al-Fath [48]: 24 berbunyi dan Dialah yang menahan tangan mereka dari kalian dan tangan kalian dari mereka di lembah Makkah setelah Allah memenangkan kalian atas mereka. Q.S. Ali Imran [3]: 159 menyebut bahwa kelembutan merupakan sebab pihak lain tidak menjauh. Hadis juga menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya. Sejarah juga mencatat bahwa Rasulullah memasuki Makkah dengan kepala yang menunduk hingga jenggotnya hampir menyentuh pelana sebagai bentuk kerendahan hati. Q.S. al-Baqarah [2]: 190 melarang melampaui batas dalam berperang. Adapun pertumpahan darah dibolehkan dalam keadaan tertentu dengan ketentuan yang ketat sehingga tidak dilarang dalam seluruh keadaan, dan hikmah pengampunan bukan sekadar kecepatan penaklukan melainkan menunjukkan tujuan dakwah yang sebenarnya.'},
{level:'HOTS',indicator:'Menentukan cara meneladani perjuangan dakwah Rasulullah bagi seorang pelajar',text:'Cara meneladani perjuangan dakwah Rasulullah bagi seorang pelajar yang paling tepat adalah ...',options:['meneladani melalui perjuangan fisik terhadap pihak yang menentang agama karena Rasulullah memperoleh kemenangan melalui perjuangan fisik','bersungguh-sungguh belajar dan berakhlak baik sebagai sarana dakwah','meneladani melalui ceramah kepada teman-teman walaupun ilmunya belum mencukupi karena menyampaikan merupakan kewajiban setiap muslim','meneladani melalui akhlak yang baik, menyampaikan kebaikan sesuai kemampuan, dan bersabar atas gangguan'],answer:1,explanation:'Q.S. Ali Imran [3]: 110 menyebut amar makruf nahi mungkar sebagai ciri umat terbaik. Hadis juga menyebut bahwa barangsiapa di antara kalian melihat kemungkaran hendaklah mengubahnya dengan tangan, dengan lisan, atau dengan hati. Hadis juga menyebut bahwa amal yang paling berat timbangannya adalah akhlak yang baik. Q.S. al-Baqarah [2]: 256 berbunyi tidak ada paksaan dalam agama. Q.S. an-Nahl [16]: 125 memerintahkan menyeru dengan hikmah, nasihat yang baik, dan berdebat dengan cara yang terbaik. Hadis juga menyebut bahwa sampaikanlah dariku walaupun satu ayat, tetapi hadis juga menyebut bahwa barangsiapa berkata tentang Al-Quran dengan pendapatnya sendiri maka hendaklah ia menyiapkan tempatnya di neraka, sehingga menyampaikan tanpa ilmu yang cukup bukan cara yang benar. Q.S. at-Taubah [9]: 122 menyebut keperluan memperdalam pengetahuan agama sebelum memberi peringatan kepada kaumnya. Adapun perjuangan fisik bukan cara yang diteladani oleh pelajar karena ketentuan berperang berlaku dalam keadaan tertentu dengan syarat yang ketat dan berada di bawah kewenangan pemimpin bukan individu.'},
{level:'HOTS',indicator:'Menganalisis keteladanan Rasulullah dalam menghadapi perbedaan pendapat di antara para sahabat',text:'Keteladanan Rasulullah dalam menghadapi perbedaan pendapat di antara para sahabat yang paling tepat adalah ...',options:['memutuskan sendiri tanpa mendengarkan pendapat sahabat karena keputusan Rasulullah berdasarkan wahyu sehingga pertimbangan manusia tidak diperlukan','mendengarkan pendapat sahabat lalu mempertimbangkannya melalui musyawarah','menunda keputusan hingga seluruh sahabat sepakat karena kesepakatan seluruh pihak merupakan syarat keputusan yang benar','mendengarkan pendapat para sahabat, mempertimbangkan bersama, dan memutuskan dengan tegas lalu bertawakal'],answer:1,explanation:'Q.S. Ali Imran [3]: 159 berbunyi dan bermusyawarahlah dengan mereka dalam urusan itu, kemudian apabila engkau telah membulatkan tekad maka bertawakallah kepada Allah. Q.S. asy-Syura [38]: 42 menggambarkan orang-orang beriman yang urusan mereka diputuskan dengan musyawarah di antara mereka. Sejarah mencatat bahwa dalam Perang Badar Rasulullah menerima usulan Hubab bin Mundzir tentang memindahkan tempat berkemah agar menguasai sumber air. Sejarah juga mencatat bahwa dalam Perang Khandaq Rasulullah menerima usulan Salman al-Farisi tentang menggali parit yang merupakan cara pertahanan yang belum dikenal di jazirah Arab. Sejarah juga mencatat bahwa dalam Perang Uhud Rasulullah bermusyawarah dan menerima pendapat mayoritas yang memilih keluar menghadapi musuh walaupun pendapatnya sendiri memilih bertahan di dalam kota. Hadis juga menyebut bahwa orang yang bermusyawarah tidak akan menyesal. Adapun memutuskan tanpa mendengarkan pendapat bukan cara yang diajarkan karena musyawarah merupakan perintah walaupun Rasulullah menerima wahyu, dan menunda keputusan hingga seluruh pihak sepakat tidak selalu mungkin karena perbedaan pendapat merupakan hal yang wajar.'},
{level:'HOTS',indicator:'Menentukan hikmah diperintahkannya meneladani Rasulullah',text:'Q.S. al-Ahzab [33]: 21 menyebut bahwa Rasulullah merupakan teladan yang baik bagi orang yang mengharap Allah dan hari akhir. Analisis yang paling tepat terhadap hikmah penyebutan tersebut adalah ...',options:['hikmahnya agar umat memiliki contoh yang nyata tentang cara menerapkan ajaran sehingga ajaran tidak berhenti pada pengertian','hikmahnya agar umat tidak memerlukan penjelasan dari pihak lain karena seluruh persoalan telah dicontohkan oleh Rasulullah secara rinci','umat memiliki contoh nyata menerapkan ajaran dalam keadaan beragam','hikmahnya karena meneladani Rasulullah merupakan amal yang paling mudah sehingga tidak memerlukan usaha yang sungguh-sungguh'],answer:2,explanation:'Q.S. al-Ahzab [33]: 21 berbunyi sesungguhnya telah ada pada diri Rasulullah teladan yang baik bagi kalian yaitu bagi orang yang mengharap Allah dan hari akhir serta banyak mengingat Allah. Q.S. Ali Imran [3]: 31 berbunyi katakanlah jika kalian mencintai Allah maka ikutilah aku niscaya Allah mencintai kalian dan mengampuni dosa-dosa kalian. Q.S. al-Qalam [68]: 4 berbunyi dan sesungguhnya engkau benar-benar berbudi pekerti yang agung. Q.S. al-Anam [6]: 50 berbunyi katakanlah aku tidak berkata kepada kalian bahwa perbendaharaan Allah ada di sisiku dan aku tidak mengetahui yang gaib serta aku tidak berkata kepada kalian bahwa aku seorang malaikat, aku tidak mengikuti melainkan apa yang diwahyukan kepadaku, yang menunjukkan bahwa Rasulullah merupakan manusia yang dapat diteladani. Hadis juga menyebut bahwa aku diutus untuk menyempurnakan akhlak yang mulia. Adapun tidak seluruh persoalan dicontohkan secara rinci karena terdapat persoalan baru yang diselesaikan melalui ijtihad dengan berpedoman pada prinsip yang diajarkan, dan meneladani bukan amal yang mudah karena memerlukan kesungguhan dan kesabaran yang berkelanjutan.'},
{level:'HOTS',indicator:'Menganalisis perjuangan sahabat dalam menjaga kemurnian Al-Quran',text:'Perjuangan para sahabat dalam menjaga kemurnian Al-Quran yang paling tepat adalah ...',options:['menghafal saja karena hafalan merupakan cara penjagaan yang paling kuat sehingga penulisan tidak diperlukan','menghafal Al-Quran dan mencatatnya pada bahan yang tersedia','menyalin Al-Quran sebanyak mungkin untuk setiap keluarga agar setiap keluarga memiliki salinan sendiri sehingga tidak bergantung pada mushaf yang disimpan oleh pemimpin','menghafal, mencatat, mengumpulkan dalam satu mushaf, dan menyatukan bacaan sehingga tidak timbul perselisihan'],answer:1,explanation:'Q.S. al-Hijr [15]: 9 berbunyi sesungguhnya Kami telah menurunkan peringatan yaitu Al-Quran dan sesungguhnya Kami benar-benar memeliharanya. Sejarah mencatat bahwa Zaid bin Tsabit diperintahkan oleh Abu Bakar mengumpulkan Al-Quran setelah usulan Umar dan ia menyatakan bahwa seandainya diperintahkan memindahkan gunung maka hal itu tidak lebih berat baginya daripada perintah mengumpulkan Al-Quran. Sejarah juga mencatat bahwa pada masa Utsman perbedaan bacaan antara pasukan Syam dan Irak mulai memicu perselisihan sehingga Hudzaifah bin Yaman melaporkan hal itu kepada Utsman lalu Utsman memerintahkan penyalinan dalam satu mushaf dengan dialek Quraisy dan mengirimkannya ke berbagai wilayah. Hadis juga menyebut bahwa sebaik-baik kalian adalah orang yang mempelajari Al-Quran dan mengajarkannya. Hadis juga menyebut bahwa orang yang mahir membaca Al-Quran bersama para malaikat yang mulia dan taat. Adapun menghafal saja tanpa mencatat bukan cara yang dipilih oleh para sahabat karena mereka mengetahui bahwa tulisan merupakan penjaga tambahan yang penting, dan menyalin untuk setiap keluarga bukan cara yang ditempuh karena keterbatasan bahan tulisan dan karena penyatuan dalam satu mushaf resmi merupakan cara menjaga kesatuan bacaan.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam menghargai kemampuan sahabat',text:'Keteladanan Rasulullah dalam menghargai kemampuan para sahabat yang paling tepat adalah ...',options:['menempatkan sahabat yang paling tua dalam seluruh tugas karena usia merupakan ukuran kemampuan yang paling dapat dipercaya','menempatkan sahabat sesuai kemampuan dan memberi kepercayaan melaksanakannya','memberi tugas yang sama kepada seluruh sahabat agar tidak ada yang merasa diutamakan sehingga tidak timbul persaingan di antara mereka','menempatkan sahabat sesuai dengan kemampuannya dan memberi kepercayaan untuk melaksanakan tugas yang sesuai'],answer:1,explanation:'Sejarah mencatat pengutusan Musab bin Umair ke Yatsrib walaupun usianya masih muda karena kemampuannya dalam menyampaikan dengan bijaksana. Sejarah juga mencatat pengutusan Muadz bin Jabal ke Yaman dengan pesan bahwa engkau akan mendatangi kaum Ahli Kitab maka ajaklah mereka kepada persaksian bahwa tidak ada Tuhan selain Allah dan bahwa aku utusan Allah. Hadis juga menyebut bahwa sebaik-baik kalian adalah yang paling baik terhadap keluarganya, dan hadis-hadis yang menyebut keutamaan masing-masing sahabat seperti Abu Bakar, Umar, Utsman, dan Ali. Hadis juga menyebut bahwa apabila seorang hakim berijtihad lalu benar maka ia memperoleh dua pahala dan apabila berijtihad lalu keliru maka ia memperoleh satu pahala, sehingga kekeliruan dalam ijtihad yang sungguh-sungguh tidak dicela. Hadis juga menyebut bahwa Allah menyukai apabila salah seorang dari kalian mengerjakan suatu amal maka mengerjakannya dengan itqan. Adapun usia bukan ukuran kemampuan karena Rasulullah mengutus pihak yang muda ketika kemampuannya sesuai, dan memberi tugas yang sama kepada seluruh sahabat tanpa mempertimbangkan kemampuan bukan cara yang menghasilkan pelaksanaan tugas yang baik.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutkannya perjuangan sahabat dalam Al-Quran',text:'Perjuangan kaum Muhajirin dan kaum Ansar disebut dalam Al-Quran sebagai pihak yang memperoleh keridhaan Allah. Analisis yang paling tepat terhadap hikmah penyebutan tersebut adalah ...',options:['hikmahnya agar umat mengetahui bentuk pengorbanan yang menghasilkan keridhaan Allah dan agar memiliki teladan yang nyata','pengorbanan meninggalkan kampung halaman dan memberi tempat kepada saudara','hikmahnya agar umat mengetahui bahwa kaum Muhajirin dan kaum Ansar telah memperoleh keridhaan sehingga tidak perlu meneladani perjuangan mereka','hikmahnya karena penyebutan itu merupakan cara memuliakan kaum Muhajirin dan kaum Ansar di hadapan umat yang datang kemudian tanpa mengandung pelajaran yang perlu diikuti'],answer:1,explanation:'Q.S. at-Taubah [9]: 100 berbunyi orang-orang yang terdahulu lagi pertama-tama masuk Islam dari golongan Muhajirin dan Ansar serta orang-orang yang mengikuti mereka dengan baik, Allah ridha kepada mereka dan mereka pun ridha kepada Allah, dan Allah menyediakan bagi mereka surga-surga yang mengalir di bawahnya sungai-sungai, mereka kekal di dalamnya selama-lamanya, itulah kemenangan yang besar. Q.S. al-Hasyr [59]: 8-9 menggambarkan keadaan kaum Muhajirin yang mencari karunia Allah dan keridhaan-Nya serta keadaan kaum Ansar yang mengutamakan orang lain atas diri mereka sendiri. Q.S. al-Hadid [57]: 10 menyebut perbedaan derajat antara orang yang berinfak sebelum penaklukan Makkah dan sesudahnya tetapi menyebut bahwa kepada masing-masing Allah telah menjanjikan kebaikan. Hadis juga menyebut bahwa janganlah kalian mencela sahabatku. Hadis juga menyebut bahwa tanda iman adalah mencintai kaum Ansar dan tanda nifaq adalah membenci kaum Ansar. Adapun penyebutan itu bukan sekadar pemuliaan tanpa pelajaran karena ayat itu menyebut orang-orang yang mengikuti mereka dengan baik sebagai pihak yang juga memperoleh keridhaan.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam menghadapi pengkhianatan',text:'Sikap Rasulullah terhadap pihak yang berkhianat terhadap kesepakatan yang paling tepat adalah ...',options:['memberi peringatan dahulu sebelum membalas pengkhianatan secara terbuka','memberi peringatan terlebih dahulu, tidak menghukum pihak yang tidak terlibat, dan tidak mengkhianati balik','membalas pengkhianatan dengan pengkhianatan yang lebih besar agar pihak yang berkhianat tidak mengulangi perbuatannya','menghukum seluruh anggota kelompok yang salah satu anggotanya berkhianat agar kelompok itu menjaga anggotanya dengan lebih sungguh-sungguh'],answer:0,explanation:'Q.S. al-Anfal [8]: 58 berbunyi dan jika engkau khawatir akan adanya pengkhianatan dari suatu kaum maka kembalikanlah perjanjian itu kepada mereka dengan cara yang jujur, sesungguhnya Allah tidak menyukai orang-orang yang berkhianat. Q.S. al-Maidah [5]: 8 berbunyi dan janganlah kebencian kalian terhadap suatu kaum mendorong kalian untuk berlaku tidak adil, berlaku adillah karena adil itu lebih dekat kepada takwa. Q.S. al-Anam [6]: 164 berbunyi dan seseorang yang berdosa tidak akan memikul dosa orang lain. Q.S. al-Baqarah [2]: 190 melarang melampaui batas. Hadis juga menyebut bahwa barangsiapa menipu maka ia bukan dari golongan Rasulullah. Sejarah mencatat bahwa Rasulullah menghadapi kelompok yang berkhianat di Madinah melalui cara yang sesuai dengan kesepakatan yang telah dibuat dan tidak menghukum anggota yang tidak terlibat. Adapun membalas pengkhianatan dengan pengkhianatan yang lebih besar merupakan bentuk melampaui batas yang dilarang, dan menghukum seluruh anggota kelompok karena pelanggaran sebagian anggotanya bukan keadilan.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah ketika menghadapi perlakuan buruk penduduk Thaif',text:'Keteladanan Rasulullah ketika menghadapi perlakuan buruk penduduk Thaif yang paling tepat adalah ...',options:['menolak pembalasan dan mendoakan petunjuk bagi penduduk yang melemparinya','meninggalkan dakwah ke luar Makkah karena penolakan di Thaif menunjukkan bahwa masyarakat di luar Makkah tidak akan menerima Islam','menolak tawaran membalas, mendoakan petunjuk bagi mereka, dan berharap kebaikan bagi keturunan mereka','menerima tawaran membalas agar penduduk Thaif menyadari akibat dari perlakuan mereka terhadap utusan Allah'],answer:0,explanation:'Sejarah mencatat bahwa Rasulullah pergi ke Thaif untuk mencari perlindungan dan menyampaikan dakwah setelah wafatnya Abu Thalib dan Khadijah serta setelah tekanan Quraisy meningkat, tetapi penduduk Thaif menghasut anak-anak dan orang-orang bodoh untuk melemparinya hingga kedua kakinya berdarah. Sejarah juga mencatat doa Rasulullah ketika itu yaitu ya Allah kepada-Mu aku mengadukan kelemahan kekuatanku dan kekurangan usahaku serta kehinaanku di hadapan manusia, Engkau Tuhan orang-orang yang lemah dan Engkau Tuhanku, kepada siapa Engkau menyerahkan aku, kepada musuh yang akan menerkamku atau kepada pihak yang menguasai urusanku, apabila Engkau tidak murka kepadaku maka aku tidak peduli. Hadis juga menyebut kisah malaikat penjaga gunung yang menawarkan untuk menimpakan akhsabain kepada penduduk Makkah atau Thaif lalu Rasulullah menolak dan menyatakan harapan agar Allah mengeluarkan dari keturunan mereka pihak yang menyembah-Nya. Q.S. Ali Imran [3]: 159 menyebut bahwa kelembutan merupakan sebab pihak lain tidak menjauh. Q.S. al-Anbiya [21]: 107 menyebut bahwa Rasulullah diutus sebagai rahmat bagi seluruh alam. Hadis juga menyebut bahwa mukmin yang kuat lebih baik dan lebih dicintai Allah daripada mukmin yang lemah, sehingga kesabaran bukan tanda kelemahan.'},
{level:'HOTS',indicator:'Menganalisis hikmah diutusnya Mush ab bin Umair sebagai duta pertama',text:'Rasulullah mengutus Musab bin Umair sebagai duta pertama ke Madinah. Analisis yang paling tepat terhadap hikmah pengutusan tersebut adalah ...',options:['hikmahnya agar Rasulullah tidak perlu berangkat sendiri ke Madinah sehingga keselamatannya lebih terjaga','hikmahnya karena Musab merupakan sahabat yang paling tua sehingga pengalamannya dapat digunakan untuk menghadapi masyarakat Madinah','masyarakat Madinah memperoleh pembinaan yang sesuai dengan keadaan mereka','hikmahnya agar masyarakat Madinah dibina melalui cara yang sesuai dengan keadaan mereka sebelum Rasulullah tiba'],answer:2,explanation:'Sejarah mencatat bahwa Rasulullah mengutus Musab bin Umair ke Yatsrib setelah Baiat Aqabah pertama untuk mengajarkan Al-Quran dan membina masyarakat yang telah masuk Islam. Sejarah juga mencatat bahwa Musab berhasil mengajak Saad bin Muadz dan Usaid bin Hudhair masuk Islam sehingga melalui keduanya banyak penduduk Madinah masuk Islam, dan riwayat menyebut bahwa tidak ada satu rumah pun dari rumah-rumah kaum Ansar kecuali telah terisi oleh orang-orang yang beriman kecuali rumah satu kabilah. Q.S. an-Nahl [16]: 125 memerintahkan menyeru dengan hikmah, nasihat yang baik, dan berdebat dengan cara yang terbaik. Hadis juga menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya. Hadis juga menganjurkan ikatlah untamu lalu bertawakallah, sehingga persiapan yang matang merupakan bagian dari tawakal. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Adapun Musab bukan sahabat yang paling tua karena ia merupakan pemuda yang berasal dari keluarga yang kaya di Makkah, dan pengutusannya bukan berarti Rasulullah tidak menjaga keselamatannya karena hijrah tetap dilakukan setelah persiapan masyarakat Madinah matang.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam mengatur perekonomian masyarakat Madinah',text:'Keteladanan Rasulullah dalam mengatur perekonomian masyarakat Madinah yang paling tepat adalah ...',options:['mendorong Muhajirin bekerja sehingga tidak menjadi beban bagi Ansar','mendorong kaum Muhajirin bekerja, menetapkan aturan transaksi yang adil, dan melarang praktik yang merugikan','menetapkan harga seluruh barang kebutuhan agar masyarakat memperoleh harga yang terjangkau tanpa mempertimbangkan kepentingan pedagang','membagikan harta kaum Ansar kepada kaum Muhajirin agar perekonomian kedua kelompok menjadi setara'],answer:0,explanation:'Sejarah mencatat bahwa Abdurrahman bin Auf tiba di Madinah tanpa harta lalu Saad bin Rabi menawarkan separuh hartanya tetapi Abdurrahman menolak dan hanya meminta ditunjukkan arah pasar, kemudian memulai usaha dengan berdagang keju dan minyak samin hingga berkembang. Hadis juga menyebut bahwa penjual dan pembeli memiliki hak khiyar selama belum berpisah dan apabila keduanya jujur serta menjelaskan maka transaksi mereka diberkahi. Hadis juga menyebut bahwa menunda pembayaran hak oleh orang yang mampu merupakan kezaliman. Hadis juga menyebut bahwa Rasulullah tidak menetapkan harga ketika masyarakat meminta beliau menetapkan harga dan menyatakan bahwa Allah yang menetapkan harga. Hadis juga menyebut bahwa barangsiapa menimbun bahan makanan dari kaum muslimin maka ia berdosa. Q.S. al-Baqarah [2]: 275 menghalalkan jual beli dan mengharamkan riba. Hadis juga menyebut bahwa tangan yang di atas lebih baik daripada tangan yang di bawah. Adapun membagikan harta kaum Ansar kepada kaum Muhajirin bukan kebijakan yang ditetapkan karena persaudaraan yang dilakukan merupakan kesediaan berbagi secara sukarela bukan pemindahan harta secara paksa, dan menetapkan harga seluruh barang bukan cara yang ditempuh karena Rasulullah membiarkan harga mengikuti keadaan pasar selama tidak terdapat praktik yang merugikan.'},
{level:'HOTS',indicator:'Menganalisis hikmah disyariatkannya musyawarah bagi Rasulullah',text:'Rasulullah diperintahkan bermusyawarah walaupun beliau menerima wahyu. Analisis yang paling tepat terhadap hikmah perintah tersebut adalah ...',options:['hikmahnya agar Rasulullah memperoleh informasi tentang keadaan masyarakat karena wahyu tidak menyampaikan informasi tentang keadaan masyarakat','umat memiliki teladan nyata tentang cara mengambil keputusan bersama','hikmahnya karena musyawarah merupakan cara menghindari tanggung jawab sehingga apabila keputusannya keliru tanggung jawabnya ditanggung bersama','hikmahnya agar umat memiliki teladan tentang cara mengambil keputusan bersama dan agar sahabat terlatih menyampaikan pendapat'],answer:1,explanation:'Q.S. Ali Imran [3]: 159 berbunyi dan bermusyawarahlah dengan mereka dalam urusan itu, kemudian apabila engkau telah membulatkan tekad maka bertawakallah kepada Allah. Q.S. asy-Syura [38]: 42 menggambarkan orang-orang beriman yang urusan mereka diputuskan dengan musyawarah di antara mereka. Hadis juga menyebut bahwa orang yang bermusyawarah tidak akan menyesal dan orang yang beristikharah tidak akan kecewa. Sejarah mencatat bahwa dalam Perang Uhud Rasulullah bermusyawarah dan menerima pendapat mayoritas walaupun pendapatnya sendiri berbeda. Sejarah juga mencatat bahwa dalam Perang Badar dan Perang Khandaq Rasulullah menerima usulan sahabat yang lebih tepat. Hadis juga menyebut bahwa setiap kalian adalah pemimpin dan akan dimintai pertanggungjawaban tentang yang dipimpinnya, sehingga tanggung jawab pemimpin tidak berpindah melalui musyawarah. Adapun wahyu menyampaikan informasi tentang keadaan masyarakat ketika diperlukan sehingga musyawarah bukan sarana memperoleh informasi yang tidak disampaikan wahyu, dan musyawarah bukan cara menghindari tanggung jawab karena pemimpin tetap bertanggung jawab atas keputusan yang diambilnya.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam memperlakukan pihak yang lemah',text:'Keteladanan Rasulullah dalam memperlakukan pihak yang lemah yang paling tepat adalah ...',options:['menghargai kedudukan pihak lemah dan memenuhi hak-hak mereka','memperlakukan pihak yang lemah dengan kasih sayang karena kasihan kepada keadaan mereka sehingga perlakuan itu merupakan bentuk belas kasihan bukan bentuk menunaikan hak','menghargai kedudukan mereka, memenuhi hak mereka, dan membebaskan mereka dari keadaan yang menindas','tidak membebani pihak yang lemah dengan tugas apa pun agar keadaannya tidak semakin sulit sehingga mereka tidak perlu bekerja'],answer:0,explanation:'Hadis juga menyebut bahwa berikanlah upah pekerja sebelum kering keringatnya. Hadis juga menyebut bahwa mereka yaitu hamba sahaya merupakan saudara kalian yang Allah jadikan di bawah tangan kalian maka barangsiapa saudaranya berada di bawah tangannya hendaklah memberinya makan dari apa yang ia makan dan memberinya pakaian dari apa yang ia pakai, dan janganlah membebani mereka dengan apa yang melebihi kemampuan mereka. Hadis juga menyebut bahwa carilah aku melalui pihak-pihak lemah kalian karena kalian diberi rezeki dan ditolong melalui pihak-pihak lemah kalian. Q.S. al-Balad [90]: 12-16 menyebut bahwa melewati rintangan yang berat yaitu memerdekakan hamba sahaya atau memberi makan pada hari kelaparan kepada anak yatim yang memiliki hubungan kerabat atau orang miskin yang sangat fakir. Q.S. al-Fajr [89]: 17-18 mengecam orang yang tidak memuliakan anak yatim dan tidak mendorong memberi makan orang miskin. Hadis juga menyebut bahwa sesungguhnya aku mengharamkan atas kalian kezaliman terhadap pihak yang lemah. Adapun memperlakukan pihak yang lemah bukan sekadar belas kasihan melainkan menunaikan hak yang telah ditetapkan oleh agama, dan tidak membebani mereka dengan tugas bukan cara yang tepat karena mereka tetap memerlukan pekerjaan yang sesuai dengan kemampuannya.'},
{level:'HOTS',indicator:'Menganalisis hikmah dijadikannya hijrah sebagai awal penanggalan Islam',text:'Hijrah dijadikan sebagai awal penanggalan Islam. Analisis yang paling tepat terhadap hikmah penetapan tersebut adalah ...',options:['hikmahnya agar umat tidak menggunakan penanggalan yang berasal dari budaya pihak lain sehingga identitas Islam terjaga','hikmahnya karena hijrah merupakan peristiwa yang paling berat sehingga umat perlu mengingat kesulitan yang dihadapi oleh generasi pertama','hikmahnya agar umat mengingat peristiwa yang menjadi titik perubahan dari keadaan tertindas menjadi masyarakat yang mandiri','umat mengingat titik perubahan dari tertindas menjadi masyarakat mandiri'],answer:3,explanation:'Sejarah mencatat bahwa pada masa Umar para sahabat bermusyawarah tentang penetapan awal penanggalan Islam dan sebagian mengusulkan kelahiran Rasulullah, sebagian mengusulan pengangkatan beliau sebagai rasul, sebagian mengusulkan wafatnya beliau, dan sebagian mengusulkan hijrah, lalu ditetapkan hijrah sebagai awal penanggalan karena hijrah merupakan peristiwa yang memisahkan antara keadaan yang sulit dan keadaan yang memungkinkan penerapan ajaran secara menyeluruh. Q.S. at-Taubah [9]: 40 menggambarkan peristiwa hijrah dan penyertaan Allah kepada Rasulullah dan sahabatnya di dalam gua. Q.S. al-Anfal [8]: 26 menyebut bahwa Allah memberi tempat menetap yaitu Madinah kepada kaum muslimin yang dahulu tertindas. Q.S. an-Nisa [4]: 100 menyebut bahwa barangsiapa berhijrah di jalan Allah niscaya ia memperoleh di muka bumi ini tempat hijrah yang luas dan rezeki yang banyak. Hadis juga menyebut bahwa amal bergantung pada niatnya dan setiap orang memperoleh apa yang diniatkannya maka barangsiapa hijrahnya kepada Allah dan Rasul-Nya maka hijrahnya kepada Allah dan Rasul-Nya. Adapun menjaga identitas merupakan manfaat tambahan bukan hikmah utama penetapan itu, dan mengingat kesulitan bukan tujuan utama karena yang diutamakan adalah mengingat perubahan yang dihasilkan melalui perjuangan.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam menyelesaikan perselisihan sebelum kenabian',text:'Keteladanan Rasulullah dalam menyelesaikan perselisihan peletakan Hajar Aswad sebelum kenabian yang paling tepat adalah ...',options:['menemukan jalan keluar yang memuaskan seluruh pihak yang berselisih','menyerahkan keputusan kepada pihak yang paling tua di antara kepala kabilah karena usia merupakan ukuran yang paling dihormati oleh masyarakat Quraisy','menyelesaikan perselisihan dengan meletakkan Hajar Aswad sendiri agar tidak ada kabilah yang memperoleh kehormatan lebih dari kabilah yang lain','menemukan jalan keluar yang memuaskan seluruh pihak sehingga perselisihan tidak berkembang menjadi pertumpahan darah'],answer:0,explanation:'Sejarah mencatat bahwa ketika Kaabah direnovasi setelah terkena banjir, kabilah-kabilah Quraisy berselisih tentang siapa yang berhak meletakkan Hajar Aswad di tempatnya dan perselisihan itu berlangsung beberapa hari hingga hampir terjadi pertumpahan darah, lalu disepakati bahwa pihak yang pertama masuk melalui pintu masjid akan memutuskan, dan yang masuk adalah Muhammad yang ketika itu belum diangkat menjadi rasul sehingga masyarakat berkata ini adalah al-Amin kami rela kepadanya. Sejarah juga mencatat cara penyelesaiannya yaitu membentangkan kain, meletakkan batu di atasnya, dan meminta setiap kepala kabilah memegang sisi kain. Hadis juga menyebut bahwa kejujuran membawa kepada kebaikan dan kebaikan membawa ke surga. Q.S. an-Nisa [4]: 58 memerintahkan memutuskan dengan adil apabila memutuskan perkara di antara manusia. Hadis juga menyebut bahwa orang yang bermusyawarah tidak akan menyesal. Adapun meletakkan sendiri tidak menyelesaikan perselisihan karena yang diperebutkan adalah kehormatan mengangkat, dan menyerahkan kepada pihak yang paling tua bukan cara yang dipilih karena cara yang dipilih menghasilkan kepuasan seluruh pihak.'},
{level:'HOTS',indicator:'Menganalisis keteladanan sahabat dalam menunaikan amanah kepemimpinan',text:'Keteladanan para sahabat dalam menunaikan amanah kepemimpinan yang paling tepat adalah ...',options:['hidup sederhana walaupun memimpin wilayah yang sangat luas','menempatkan keluarga dalam jabatan agar dapat dipercaya karena keluarga merupakan pihak yang paling dapat diandalkan dalam menjaga amanah','hidup sederhana, berhati-hati terhadap harta umat, dan mengembalikan kelebihan yang diterimanya','menolak seluruh bagian dari baitul mal agar tidak terkena harta umat sehingga memimpin tanpa memperoleh penghasilan'],answer:0,explanation:'Sejarah mencatat bahwa Abu Bakar tetap berdagang setelah menjadi khalifah hingga para sahabat menetapkan gaji untuknya dari baitul mal karena perdagangannya mengganggu urusan umat, dan ketika mendekati ajalnya ia mengembalikan sisa harta yang telah diterimanya beserta kebun dan perabot yang digunakannya. Sejarah juga mencatat kisah Ibn al-Lutbiyyah yang ditugaskan mengumpulkan zakat lalu kembali membawa sebagian hadiah dan berkata ini untuk kalian dan ini dihadiahkan kepadaku, lalu Rasulullah bersabda di mimbar mengapa tidak duduk saja di rumah ayahnya dan melihat apakah ia diberi hadiah, yang menunjukkan kehati-hatian terhadap hadiah yang berkaitan dengan jabatan. Sejarah juga mencatat Umar yang menetapkan bagian untuk dirinya setara dengan bagian seorang dari kaum muslimin dan yang menolak memakai pakaian yang lebih baik ketika menerima utusan dari Persia. Hadis juga menyebut bahwa setiap kalian adalah pemimpin dan akan dimintai pertanggungjawaban tentang yang dipimpinnya. Hadis juga menyebut bahwa sebaik-baik harta adalah harta yang berada di tangan orang saleh. Adapun menolak seluruh bagian dari baitul mal bukan cara yang ditempuh karena pemimpin yang mengabdikan waktunya untuk urusan umat berhak memperoleh bagian yang mencukupi, dan menempatkan keluarga dalam jabatan karena hubungan keluarga bukan cara yang ditempuh karena yang menjadi ukuran adalah kemampuan.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam mendidik generasi muda',text:'Keteladanan Rasulullah dalam mendidik generasi muda yang paling tepat adalah ...',options:['memberi kepercayaan sesuai kemampuan dan membina dengan kasih sayang','memberi tugas yang berat kepada generasi muda agar kemampuannya cepat berkembang karena kesulitan merupakan sarana pendidikan yang paling efektif','tidak memberi kepercayaan kepada generasi muda karena usia muda merupakan tanda bahwa kemampuannya belum mencukupi untuk memimpin','memberi kepercayaan sesuai kemampuan, membina dengan kasih sayang, dan tidak merendahkan walaupun usianya muda'],answer:0,explanation:'Sejarah mencatat pengangkatan Usamah bin Zaid yang berusia sekitar delapan belas tahun sebagai pemimpin pasukan yang di dalamnya terdapat Abu Bakar dan Umar sehingga sebagian sahabat menyampaikan keberatan lalu Rasulullah menegaskan pengangkatannya. Sejarah juga mencatat kisah seorang pemuda yang datang meminta izin untuk berzina lalu Rasulullah memintanya mendekat dan bertanya apakah engkau menyukainya untuk ibumu, apakah engkau menyukainya untuk putrimu, apakah engkau menyukainya untuk saudara perempuanmu, hingga pemuda itu menyatakan tidak ada yang menyukainya, lalu Rasulullah bersabda demikian pula seluruh manusia tidak menyukainya, kemudian meletakkan tangan beliau di dada pemuda itu dan berdoa memohon ampunan baginya, sehingga pemuda itu tidak lagi menoleh kepada perbuatan itu. Hadis juga menyebut bahwa Rasulullah memberi salam kepada anak-anak yang sedang bermain. Hadis juga menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya. Hadis juga menyebut bahwa mukmin yang kuat lebih baik dan lebih dicintai Allah daripada mukmin yang lemah. Adapun memberi tugas yang melebihi kemampuan bukan cara yang diajarkan karena tugas perlu disesuaikan dengan kemampuan, dan tidak memberi kepercayaan kepada generasi muda menghilangkan kesempatan berkembang karena kepercayaan yang sesuai kemampuan merupakan sarana pendidikan.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutkannya bahwa Islam tersebar melalui akhlak',text:'Islam tersebar luas melalui akhlak para pembawanya bukan hanya melalui penjelasan. Analisis yang paling tepat terhadap hikmah keadaan tersebut adalah ...',options:['hikmahnya agar umat tidak memerlukan penjelasan tentang ajaran karena akhlak yang baik telah cukup menjadi sarana dakwah','hikmahnya agar umat memahami bahwa keteladanan akhlak merupakan sarana dakwah yang paling berpengaruh','keteladanan akhlak merupakan sarana dakwah yang paling berpengaruh','hikmahnya karena masyarakat pada masa itu belum mampu memahami penjelasan sehingga memerlukan contoh perilaku untuk menerima ajaran'],answer:2,explanation:'Q.S. as-Saff [61]: 2-3 mengecam orang yang mengatakan apa yang tidak dikerjakannya dan menyebut bahwa hal itu sangat dibenci di sisi Allah, sehingga kesesuaian antara penjelasan dan perilaku merupakan syarat pengaruh penyampaian. Q.S. al-Qalam [68]: 4 berbunyi dan sesungguhnya engkau benar-benar berbudi pekerti yang agung. Q.S. Ali Imran [3]: 159 menyebut bahwa kelembutan merupakan sebab pihak lain tidak menjauh. Hadis juga menyebut bahwa aku diutus untuk menyempurnakan akhlak yang mulia. Hadis juga menyebut bahwa amal yang paling berat timbangannya adalah akhlak yang baik. Hadis juga menyebut bahwa sebaik-baik manusia adalah yang paling bermanfaat bagi manusia. Sejarah mencatat penyebaran Islam di berbagai wilayah melalui jalur perdagangan yang dilakukan oleh pedagang muslim yang dikenal jujur sehingga masyarakat setempat tertarik kepada ajaran yang menghasilkan perilaku yang demikian. Adapun penjelasan tetap diperlukan karena akhlak yang baik tanpa penjelasan tidak menyampaikan isi ajaran secara lengkap, dan masyarakat pada masa itu mampu memahami penjelasan sebagaimana tercatat dalam dialog antara Rasulullah dan para pembesar Quraisy.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam menjaga hubungan dengan pihak yang berbeda keyakinan',text:'Keteladanan Rasulullah dalam menjaga hubungan dengan pihak yang berbeda keyakinan di Madinah yang paling tepat adalah ...',options:['membuat kesepakatan yang menjamin hak, berlaku adil dalam memutuskan perkara, dan tidak memaksa dalam urusan keyakinan','berlaku adil dalam memutuskan perkara hanya ketika pihak yang berbeda keyakinan yang menuntut keadilan sehingga keadilan bukan diberikan secara sukarela','membuat kesepakatan yang menguntungkan kaum muslimin karena kesepakatan dengan pihak yang berbeda keyakinan merupakan sarana memperoleh kekuatan','membuat kesepakatan yang menjamin hak seluruh kelompok dan berlaku adil'],answer:3,explanation:'Sejarah mencatat Piagam Madinah yang mengatur hubungan antara kaum muslimin, kelompok Yahudi dari Bani Qainuqa, Bani Nadhir, dan Bani Quraizah, serta kelompok lain di Madinah dengan ketentuan tentang hak, kewajiban, dan penyelesaian perselisihan. Q.S. an-Nisa [4]: 105-113 menceritakan peristiwa ketika perisai dicuri lalu tuduhan diarahkan kepada seorang Yahudi dan Allah menjelaskan keadaan yang sebenarnya serta melarang Rasulullah membela pihak yang berkhianat, sehingga keadilan ditegakkan walaupun menguntungkan pihak yang berbeda keyakinan. Q.S. al-Baqarah [2]: 256 berbunyi tidak ada paksaan dalam agama. Q.S. al-Mumtahanah [60]: 8 berbunyi Allah tidak melarang kalian berbuat baik dan berlaku adil terhadap orang-orang yang tidak memerangi kalian karena agama dan tidak mengusir kalian dari kampung halaman kalian. Q.S. al-Hajj [22]: 40 menyebut bahwa seandainya Allah tidak menolak keganasan sebagian manusia dengan sebagian yang lain tentulah telah dirobohkan biara-biara, gereja-gereja, tempat ibadah Yahudi, dan masjid-masjid. Adapun kesepakatan yang dibuat bukan kesepakatan yang menguntungkan satu pihak karena kesepakatan yang demikian tidak menghasilkan keamanan bersama, dan keadilan diberikan kepada seluruh pihak bukan hanya ketika dituntut karena keadilan merupakan kewajiban yang tidak bergantung pada tuntutan.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutkannya bahwa para rasul menghadapi ujian yang paling berat',text:'Manusia yang paling berat ujiannya adalah para nabi kemudian yang paling serupa dengan mereka. Analisis yang paling tepat terhadap hikmah sebutan tersebut adalah ...',options:['hikmahnya agar umat tidak berusaha menghindari ujian karena menghindari ujian berarti menghindari kedudukan yang tinggi','hikmahnya karena ujian yang berat hanya berlaku bagi para nabi sehingga umat yang datang kemudian tidak menghadapi ujian yang berarti','ujian berat bukan tanda Allah tidak menyayangi hamba yang dicintai-Nya','hikmahnya agar umat tidak menganggap ujian sebagai tanda bahwa Allah tidak menyayanginya'],answer:2,explanation:'Hadis juga menyebut bahwa manusia yang paling berat ujiannya adalah para nabi kemudian yang paling serupa dengan mereka kemudian yang paling serupa dengan mereka, seseorang diuji sesuai dengan kadar agamanya, apabila agamanya kuat maka ujiannya diperberat dan apabila agamanya lemah maka ia diuji sesuai dengan kadar agamanya, dan hamba senantiasa diuji hingga ia berjalan di muka bumi tanpa dosa. Q.S. al-Ankabut [29]: 2-3 berbunyi apakah manusia mengira bahwa mereka akan dibiarkan hanya dengan mengatakan kami telah beriman sedangkan mereka tidak diuji. Hadis juga menyebut bahwa tidaklah seorang muslim tertimpa kelelahan, penyakit, kesedihan, kesusahan, gangguan, dan gundah gulana bahkan duri yang menusuknya melainkan Allah menghapus sebagian kesalahannya. Q.S. az-Zumar [39]: 10 menyebut bahwa orang yang bersabar disempurnakan pahalanya tanpa perhitungan. Hadis juga menyebut bahwa perkara orang mukmin seluruhnya baik yaitu apabila memperoleh nikmat ia bersyukur dan apabila tertimpa musibah ia bersabar. Adapun menghindari ujian yang tidak dapat dihindari bukan pilihan manusia, tetapi berusaha menjauhi sebab yang mendatangkan bencana tetap diperintahkan sebagaimana kisah Umar yang tidak memasuki wilayah yang terkena wabah, dan umat yang datang kemudian tetap menghadapi ujian walaupun tidak seberat ujian para nabi.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam menghadapi kekalahan pada Perang Uhud',text:'Sikap Rasulullah setelah pasukan mengalami kekalahan pada Perang Uhud yang paling tepat adalah ...',options:['menyalahkan sahabat yang melakukan kekeliruan agar kekeliruan yang sama tidak terulang pada pertempuran berikutnya','tidak menyalahkan sahabat yang melakukan kekeliruan, mengevaluasi sebab kekalahan, dan mempersiapkan diri untuk menghadapi kemungkinan berikutnya','menghentikan kebiasaan bermusyawarah karena musyawarah menghasilkan keputusan yang menyebabkan kekalahan','tidak menyalahkan yang keliru dan mengevaluasi sebab kekalahannya'],answer:3,explanation:'Q.S. Ali Imran [3]: 159 berbunyi maka berkat rahmat Allah engkau berlaku lemah lembut terhadap mereka, dan seandainya engkau bersikap keras dan berhati kasar niscaya mereka menjauh dari sekitarmu, maka maafkanlah mereka dan mohonkanlah ampun bagi mereka serta bermusyawarahlah dengan mereka dalam urusan itu, sehingga ayat itu turun setelah Perang Uhud dan tetap memerintahkan bermusyawarah. Q.S. Ali Imran [3]: 152-155 menjelaskan sebab kekalahan yaitu ketidaktaatan sebagian pasukan terhadap perintah, perselisihan, dan godaan setan atas sebagian kekeliruan yang telah lalu, lalu menyebut bahwa Allah telah memaafkan mereka. Sejarah juga mencatat bahwa Rasulullah terluka pada Perang Uhud tetapi tetap berada di medan. Sejarah juga mencatat peristiwa ketika Rasulullah mengeluarkan pasukan pada hari berikutnya setelah Uhud walaupun dalam keadaan terluka sehingga kaum Quraisy yang mendengar tidak jadi kembali menyerang. Hadis juga menyebut bahwa apabila seorang hakim berijtihad lalu keliru maka ia memperoleh satu pahala. Q.S. al-Baqarah [2]: 216 menyebut bahwa boleh jadi manusia membenci sesuatu padahal sesuatu itu baik bagi mereka.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutkannya kesabaran para sahabat yang berhijrah',text:'Kesabaran kaum Muhajirin yang meninggalkan kampung halaman dan hartanya disebut dalam Al-Quran. Analisis yang paling tepat terhadap hikmah penyebutan tersebut adalah ...',options:['hikmahnya agar umat tidak terikat pada harta dan kampung halaman sehingga keduanya perlu ditinggalkan untuk memperoleh kedudukan yang tinggi','hikmahnya karena pengorbanan kaum Muhajirin merupakan syarat sah keimanan sehingga umat yang datang kemudian perlu melakukan pengorbanan yang serupa','hikmahnya agar umat memahami bahwa mempertahankan keimanan dapat memerlukan pengorbanan harta dan kenyamanan','mempertahankan iman dapat memerlukan pengorbanan harta dan kampung halaman'],answer:3,explanation:'Q.S. al-Hasyr [59]: 8 berbunyi bagi orang fakir yang berhijrah yang diusir dari kampung halaman dan dari harta benda mereka karena mencari karunia Allah dan keridhaan-Nya serta menolong Allah dan Rasul-Nya, mereka itulah orang-orang yang benar. Q.S. an-Nahl [16]: 41 berbunyi dan orang-orang yang berhijrah karena Allah setelah mereka dizalimi pasti Kami akan memberikan tempat yang baik kepada mereka di dunia dan sungguh pahala di akhirat lebih besar kalau mereka mengetahui. Q.S. al-Ankabut [29]: 26-27 menyebut bahwa Allah memberi tempat hijrah yang luas dan rezeki yang banyak. Hadis juga menyebut bahwa tidak ada hijrah setelah penaklukan Makkah tetapi yang ada adalah kesungguhan dan niat, dan apabila kalian diperintahkan berperang maka berangkatlah, sehingga hijrah dalam pengertian perpindahan tidak lagi diwajibkan tetapi hijrah dalam pengertian meninggalkan hal yang dilarang tetap berlaku. Hadis juga menyebut bahwa seorang muhajir adalah orang yang meninggalkan apa yang dilarang Allah. Adapun meninggalkan harta dan kampung halaman bukan keharusan bagi umat yang datang kemudian karena kewajiban hijrah dalam pengertian perpindahan telah berakhir setelah penaklukan Makkah, dan pengorbanan kaum Muhajirin bukan syarat sah keimanan bagi umat yang datang kemudian melainkan teladan dalam mempertahankan keimanan.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam menyampaikan kabar gembira dan peringatan',text:'Keteladanan Rasulullah dalam menyampaikan kabar gembira dan peringatan yang paling tepat adalah ...',options:['menyampaikan kabar gembira lebih banyak daripada peringatan karena kabar gembira lebih disukai oleh masyarakat sehingga penyampaiannya lebih diterima','menyampaikan kabar gembira dan peringatan secara seimbang sesuai kadarnya','menyampaikan keduanya secara seimbang dan menyesuaikan kadar penyampaian dengan keadaan pihak yang diajak','menyampaikan peringatan lebih banyak daripada kabar gembira karena peringatan lebih menghasilkan perubahan perilaku sehingga masyarakat segera meninggalkan dosa'],answer:1,explanation:'Q.S. al-Kahfi [18]: 56 berbunyi dan Kami tidak mengutus rasul-rasul melainkan sebagai pembawa kabar gembira dan pemberi peringatan. Q.S. al-Araf [7]: 56 berbunyi dan berdoalah kepada-Nya dengan rasa takut dan harap, sesungguhnya rahmat Allah sangat dekat kepada orang-orang yang berbuat kebaikan. Hadis juga menyebut bahwa sampaikanlah kabar gembira dan jangan membuat orang menjauh, mudahkanlah dan jangan mempersulit. Hadis juga menyebut bahwa agama ini mudah dan tidak ada orang yang mempersulit diri dalam agama melainkan agama itu mengalahkannya. Hadis juga menyebut kisah pengutusan Muadz bin Jabal ke Yaman dengan pesan bahwa engkau akan mendatangi kaum Ahli Kitab maka hendaklah yang pertama kali engkau serukan kepada mereka adalah persaksian bahwa tidak ada Tuhan selain Allah dan bahwa aku utusan Allah. Q.S. Yusuf [12]: 87 melarang berputus asa dari rahmat Allah. Q.S. al-Araf [7]: 99 menyebut bahwa tidak ada yang merasa aman dari rencana Allah kecuali orang-orang yang merugi. Adapun memilih salah satu lebih banyak daripada yang lain secara mutlak bukan cara yang diajarkan karena yang diajarkan adalah menyesuaikan dengan keadaan pihak yang diajak.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutkannya bahwa Rasulullah tidak meminta upah atas dakwahnya',text:'Rasulullah menyatakan bahwa beliau tidak meminta upah atas penyampaian ajaran. Analisis yang paling tepat terhadap hikmah pernyataan tersebut adalah ...',options:['hikmahnya agar penyampaian ajaran dipercaya sebagai penyampaian yang tulus dan agar tidak ada pihak yang memperoleh keuntungan materi dari dakwah','penyampaian ajaran dipercaya sebagai penyampaian yang tulus tanpa pamrih','hikmahnya karena meminta upah atas dakwah merupakan perbuatan yang haram sehingga seluruh bentuk imbalan atas kegiatan keagamaan dilarang','hikmahnya agar masyarakat tidak terbebani oleh kewajiban membayar sehingga lebih banyak pihak yang bersedia mendengarkan ajaran'],answer:1,explanation:'Q.S. al-Anam [6]: 90 berbunyi mereka itulah orang-orang yang telah diberi petunjuk oleh Allah maka ikutilah petunjuk mereka, katakanlah aku tidak meminta upah kepada kalian atas penyampaian ini, itu tidak lain hanyalah peringatan bagi seluruh alam. Q.S. asy-Syuara [26]: 109 berbunyi dan aku tidak meminta upah kepada kalian atas penyampaian itu, upahku tidak lain hanyalah dari Tuhan seluruh alam. Q.S. Hud [11]: 29 juga berbunyi wahai kaumku aku tidak meminta harta kepada kalian atas penyampaian ini, upahku tidak lain dari Allah. Hadis juga menyebut bahwa barangsiapa menuntut ilmu untuk memperoleh perhatian manusia maka ia masuk neraka. Q.S. al-Baqarah [2]: 41 melarang menukar ayat-ayat Allah dengan harga yang murah. Hadis juga menyebut bahwa amal bergantung pada niatnya. Adapun imbalan atas kegiatan yang berkaitan dengan pengajaran agama tidak dilarang secara mutlak karena terdapat ketentuan yang membolehkan upah atas pengajaran Al-Quran dan atas tugas keagamaan yang ditunaikan, sehingga yang dilarang adalah menjadikan dakwah sebagai alat memperoleh keuntungan dengan menyesuaikan isi demi imbalan.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam menghormati kesepakatan gencatan senjata',text:'Keteladanan Rasulullah dalam menghormati kesepakatan gencatan senjata pada perjanjian Hudaibiyah yang paling tepat adalah ...',options:['mengembalikan pihak yang datang dari Makkah sesuai kesepakatan walaupun pengembalian itu terasa berat','melanggar kesepakatan ketika mengetahui bahwa pihak lawan tidak menepati seluruh ketentuan karena kesepakatan hanya berlaku ketika kedua pihak menepatinya','mengembalikan pihak yang datang sesuai isi kesepakatan walaupun terasa berat','tidak mengembalikan pihak yang datang dari Makkah karena mengembalikan mereka kepada penyiksaan merupakan perbuatan yang tidak dibenarkan'],answer:2,explanation:'Sejarah mencatat isi perjanjian Hudaibiyah yang di antaranya adalah bahwa barangsiapa dari pihak Quraisy datang kepada Muhammad tanpa izin walinya maka ia dikembalikan, dan barangsiapa dari pihak Muhammad datang kepada Quraisy maka ia tidak dikembalikan, dan ketentuan itu terasa berat bagi kaum muslimin tetapi Rasulullah tetap menepatinya. Sejarah juga mencatat bahwa Abu Jandal yang datang dalam keadaan terbelenggu dikembalikan kepada walinya lalu Rasulullah menyatakan bahwa Allah akan memberi jalan keluar baginya dan bagi pihak yang bersamanya. Sejarah juga mencatat bahwa setelah dikembalikan pihak-pihak itu membentuk kelompok yang berada di luar Madinah dan tidak terikat oleh kesepakatan sehingga tidak melanggar kesepakatan tetapi mengganggu jalur perdagangan Quraisy hingga Quraisy sendiri meminta agar ketentuan itu dibatalkan. Q.S. an-Nahl [16]: 91 memerintahkan memenuhi janji. Q.S. al-Isra [17]: 34 menyebut bahwa janji akan dimintai pertanggungjawabannya. Q.S. al-Baqarah [2]: 216 menyebut bahwa boleh jadi manusia membenci sesuatu padahal sesuatu itu baik bagi mereka. Adapun melanggar kesepakatan bukan cara yang ditempuh karena kesetiaan terhadap kesepakatan merupakan ciri keimanan, dan tidak mengembalikan pihak yang datang merupakan pelanggaran terhadap kesepakatan yang telah dibuat.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutkannya bahwa Rasulullah merupakan rahmat bagi seluruh alam',text:'Q.S. al-Anbiya [21]: 107 menyebut bahwa Rasulullah diutus sebagai rahmat bagi seluruh alam. Analisis yang paling tepat terhadap hikmah penyebutan tersebut adalah ...',options:['hikmahnya karena rahmat merupakan sifat yang paling utama sehingga ajaran yang lain seperti keadilan tidak perlu ditegakkan apabila rahmat telah diberikan','hikmahnya agar umat memahami bahwa ajaran yang dibawa menghasilkan kebaikan bagi seluruh makhluk bukan hanya bagi pengikutnya','ajaran beliau menghasilkan kebaikan bagi seluruh makhluk termasuk yang kafir','hikmahnya agar seluruh manusia beriman kepada Rasulullah karena rahmat hanya berlaku bagi pihak yang beriman kepadanya'],answer:2,explanation:'Q.S. al-Anbiya [21]: 107 berbunyi dan Kami tidak mengutus engkau melainkan sebagai rahmat bagi seluruh alam. Q.S. al-Mumtahanah [60]: 8 menyebut berbuat baik dan berlaku adil terhadap orang yang tidak memerangi karena agama. Q.S. al-Hajj [22]: 40 menyebut bahwa seandainya Allah tidak menolak keganasan sebagian manusia dengan sebagian yang lain tentulah telah dirobohkan biara-biara, gereja-gereja, tempat ibadah Yahudi, dan masjid-masjid. Hadis juga menyebut bahwa dalam setiap hati yang basah terdapat pahala yaitu berbuat baik kepada setiap makhluk yang hidup. Hadis juga menyebut bahwa sayangi lah penduduk bumi niscaya penduduk langit menyayangi kalian. Hadis juga menyebut kisah Rasulullah yang berdoa untuk kaumnya ketika mereka melemparinya sambil menyatakan ya Allah berilah petunjuk kepada kaumku karena mereka tidak mengetahui. Q.S. al-Baqarah [2]: 256 berbunyi tidak ada paksaan dalam agama, sehingga beriman merupakan pilihan yang tidak dipaksakan walaupun rahmat ajaran itu berlaku bagi seluruh alam. Adapun keadilan merupakan bagian dari rahmat karena keadilan melindungi pihak yang lemah sehingga keduanya tidak dapat dipisahkan.'},
{level:'HOTS',indicator:'Menentukan cara meneladani perjuangan dakwah Rasulullah dan para sahabat dalam keadaan sekarang',text:'Bentuk peneladanan perjuangan dakwah Rasulullah dan para sahabat pada masa sekarang yang paling tepat adalah ...',options:['tidak menyampaikan ajaran kepada masyarakat yang telah menolak karena penyampaian kepada pihak yang menolak tidak akan menghasilkan penerimaan','menyampaikan ajaran melalui cara yang tersedia dengan akhlak yang baik, bersabar atas penolakan, dan tidak memaksakan penerimaan','menyampaikan ajaran dengan cara yang tegas agar masyarakat segera menyadari kesalahannya walaupun cara itu menghasilkan penolakan','menyampaikan ajaran melalui cara yang tersedia sesuai kemampuan masing-masing'],answer:3,explanation:'Q.S. an-Nahl [16]: 125 memerintahkan menyeru dengan hikmah, nasihat yang baik, dan berdebat dengan cara yang terbaik. Q.S. al-Baqarah [2]: 256 berbunyi tidak ada paksaan dalam agama. Q.S. al-Baqarah [2]: 272 berbunyi bukan kewajibanmu memberi mereka petunjuk tetapi Allah memberi petunjuk kepada siapa yang dikehendaki-Nya. Q.S. Ali Imran [3]: 159 menyebut bahwa kelembutan merupakan sebab pihak lain tidak menjauh. Q.S. an-Nahl [16]: 43 memerintahkan bertanya kepada ahli pengetahuan apabila tidak mengetahui. Hadis juga menyebut bahwa barangsiapa berkata tentang Al-Quran dengan pendapatnya sendiri maka hendaklah ia menyiapkan tempatnya di neraka, sehingga menyampaikan tanpa ilmu bukan cara yang benar. Q.S. al-Maidah [5]: 2 memerintahkan tolong-menolong dalam kebaikan dan takwa. Hadis juga menyebut bahwa amal bergantung pada niatnya. Adapun menyampaikan dengan cara yang tegas dibolehkan dalam keadaan tertentu tetapi kelembutan lebih sering menghasilkan penerimaan, dan tidak menyampaikan kepada pihak yang telah menolak bukan cara yang diajarkan karena Rasulullah tetap menyampaikan kepada kaum Quraisy selama bertahun-tahun walaupun mereka menolak.'},
{level:'HOTS',indicator:'Menganalisis hikmah dijadikannya perjuangan dakwah sebagai kisah yang diceritakan berulang dalam Al-Quran',text:'Kisah perjuangan dakwah diceritakan berulang dalam Al-Quran. Analisis yang paling tepat terhadap hikmah pengulangan tersebut adalah ...',options:['hikmahnya agar umat menghafal kisah itu karena hafalan merupakan tujuan utama pengulangan dalam Al-Quran','pelajaran dari kisah tertanam melalui pengulangan yang menguatkan ingatan','hikmahnya agar pelajaran dari kisah itu tertanam dalam hati dan agar umat menghadapi keadaan yang serupa dengan kesiapan','hikmahnya karena kisah perjuangan dakwah merupakan bagian yang paling panjang dalam Al-Quran sehingga memerlukan pengulangan agar seluruhnya tersampaikan'],answer:1,explanation:'Q.S. Hud [11]: 120 berbunyi dan semua kisah rasul-rasul Kami ceritakan kepadamu ialah kisah-kisah yang dengannya Kami teguhkan hatimu, dan dalam ini telah datang kepadamu kebenaran serta pengajaran dan peringatan bagi orang-orang yang beriman. Q.S. Yusuf [12]: 111 berbunyi sesungguhnya pada kisah-kisah mereka itu terdapat pelajaran bagi orang-orang yang berakal, dan Al-Quran itu bukanlah cerita yang dibuat-buat. Q.S. al-Ankabut [29]: 2-3 menyebut bahwa umat sebelum kaum muslimin juga diuji. Hadis juga menyebut bahwa manusia yang paling berat ujiannya adalah para nabi kemudian yang paling serupa dengan mereka. Q.S. al-Ahzab [33]: 21 menyebut bahwa Rasulullah merupakan teladan yang baik. Q.S. Shad [38]: 29 menyebut agar diperhatikan ayat-ayatnya dan agar orang yang berakal mengambil pelajaran. Adapun menghafal kisah merupakan manfaat tambahan bukan tujuan utama pengulangan karena tujuannya adalah mengambil pelajaran, dan pengulangan kisah dalam Al-Quran bukan disebabkan oleh panjangnya kisah melainkan oleh keperluan penguatan pelajaran.'},
{level:'HOTS',indicator:'Menentukan keteladanan Rasulullah dalam menjaga persatuan masyarakat Madinah',text:'Keteladanan Rasulullah dalam menjaga persatuan masyarakat Madinah yang paling tepat adalah ...',options:['menyatukan masyarakat melalui ikatan akidah yang melampaui ikatan suku','menyatukan masyarakat dengan menghilangkan identitas suku sehingga tidak ada pihak yang membanggakan sukunya','menyatukan melalui ikatan akidah, menyelesaikan perselisihan dengan adil, dan tidak membiarkan pihak yang memecah belah','menyerahkan penyelesaian perselisihan kepada kepala suku masing-masing karena kepala suku paling memahami keadaan warganya'],answer:0,explanation:'Q.S. Ali Imran [3]: 103 berbunyi dan berpegang teguhlah kalian kepada tali Allah seluruhnya dan janganlah bercerai-berai, dan ingatlah nikmat Allah kepada kalian ketika kalian dahulu bermusuh-musuhan maka Allah mempersatukan hati kalian lalu jadilah kalian karena nikmat Allah orang-orang yang bersaudara. Sejarah mencatat bahwa Aus dan Khazraj telah berperang selama puluhan tahun termasuk Perang Bu ats lalu perselisihan itu berakhir setelah keduanya masuk Islam. Sejarah juga mencatat peristiwa ketika seorang Yahudi mengutus seseorang untuk mengingatkan kaum Aus dan Khazraj tentang peperangan mereka dahulu sehingga kedua kelompok hampir bertikai lalu Rasulullah datang dan menjelaskan bahwa mereka telah dimuliakan oleh Islam sehingga keduanya menyadari tipuan itu dan berdamai. Q.S. al-Hujurat [49]: 10 berbunyi sesungguhnya orang-orang mukmin itu bersaudara maka damaikanlah antara kedua saudara kalian. Q.S. al-Hujurat [49]: 13 menyebut bahwa yang paling mulia di sisi Allah adalah yang paling bertakwa. Hadis juga menyebut bahwa Allah telah menghilangkan kesombongan pada masa jahiliah dan membanggakan nenek moyang. Adapun menghilangkan identitas suku bukan cara yang ditempuh karena identitas suku tetap ada tetapi kebanggaan atas suku yang menghasilkan perendahan terhadap suku lain yang dihilangkan, dan menyerahkan penyelesaian perselisihan kepada kepala suku bukan cara yang ditempuh karena Rasulullah sendiri yang menyelesaikan dengan adil.'}
]});
